import type { AdvancedQuestion, AdvancedStep } from "../advanced-lessons";

// sqr rota las opciones según `shift` para que la respuesta correcta no quede
// siempre en el mismo índice (evita el patrón "la correcta siempre es A").
const sqr = (prompt: string, correct: string, wrong: [string, string, string], shift: number, why: string, code = ""): AdvancedQuestion => {
  const all = [correct, ...wrong];
  const options = all.map((_, k) => all[(k + shift) % 4]);
  const answer = (4 - shift) % 4;
  return { prompt, options, answer, why, code };
};

export const stepsM13M15: AdvancedStep[] = [
 {id:"m13-exceptions",title:"Excepciones en C#",summary:"Una excepción es un objeto (derivado de System.Exception) que representa un error en tiempo de ejecución. .NET tiene una jerarquía: Exception → SystemException → tipos concretos como ArgumentException, InvalidOperationException, IndexOutOfRangeException o IOException. Si nadie captura una excepción, el proceso termina mostrando el stack trace.",code:"try\n{\n    int[] numeros = { 1, 2, 3 };\n    Console.WriteLine(numeros[5]);\n}\ncatch (IndexOutOfRangeException ex)\n{\n    Console.WriteLine($\"Error: {ex.Message}\");\n}",questions:[
  sqr("¿De qué clase deben derivar, directa o indirectamente, todos los tipos de excepción en .NET?","System.Exception",["System.Object únicamente","System.SystemException obligatoriamente","System.ApplicationException obligatoriamente"],0,"Toda excepción, incluidas las personalizadas, debe heredar (directa o indirectamente) de System.Exception."),
  sqr("¿Qué excepción lanza en tiempo de ejecución este código?","IndexOutOfRangeException",["ArgumentOutOfRangeException","InvalidOperationException","NullReferenceException"],1,"Acceder a un índice de arreglo fuera de rango lanza IndexOutOfRangeException; ArgumentOutOfRangeException es para validar argumentos de métodos, no accesos directos a arreglos.","int[] datos = { 10, 20, 30 };\nConsole.WriteLine(datos[10]);"),
  sqr("¿Qué excepción se produce al invocar un método o leer una propiedad sobre una referencia que vale null?","NullReferenceException",["ArgumentNullException","InvalidCastException","StackOverflowException"],2,"Desreferenciar null (llamar un método o acceder a un miembro) produce NullReferenceException en tiempo de ejecución."),
  sqr("¿Qué excepción se lanza al hacer un cast inválido entre tipos incompatibles con (Tipo)objeto?","InvalidCastException",["FormatException","NotSupportedException","ArgumentException"],3,"Un cast explícito que no puede realizarse en tiempo de ejecución lanza InvalidCastException."),
  sqr("¿Qué relación hay entre ArgumentNullException y ArgumentException?","ArgumentNullException deriva de ArgumentException; es el caso específico de un argumento nulo",["Son clases sin relación de herencia","ArgumentException deriva de ArgumentNullException","Son exactamente la misma clase con dos nombres"],1,"ArgumentNullException es una subclase más específica de ArgumentException, pensada para el caso de argumentos null."),
  sqr("¿Qué imprime este código?","Infinity",["Lanza DivideByZeroException","0","Lanza NullReferenceException"],2,"La división de punto flotante (double) por cero NO lanza excepción: produce double.PositiveInfinity. Solo la división entera por cero lanza DivideByZeroException.","double r = 10.0 / 0;\nConsole.WriteLine(r);"),
  sqr("¿Qué ocurre al ejecutar este código?","Lanza System.DivideByZeroException en tiempo de ejecución",["Imprime Infinity","Imprime 0","Falla en tiempo de compilación"],3,"La división entera (int) por cero lanza DivideByZeroException en tiempo de ejecución; esto es distinto de la división con double.","int a = 10;\nint b = 0;\nConsole.WriteLine(a / b);"),
  sqr("¿Qué le sucede a una aplicación de consola si una excepción no es capturada por ningún try/catch?","El proceso termina, imprime el stack trace en la salida de error y retorna un código de salida distinto de cero",["Continúa ejecutándose ignorando la línea fallida","Se reinicia automáticamente el proceso","La excepción se convierte silenciosamente en null"],0,"Una excepción no manejada termina el proceso; .NET imprime tipo, mensaje y stack trace, y el código de salida es distinto de cero."),
  sqr("¿Qué información provee Exception.StackTrace?","La secuencia de llamadas a métodos que llevó al punto donde se lanzó la excepción",["El mensaje de error legible para el usuario","El valor de todas las variables locales","El nombre del archivo donde se debe corregir el bug"],1,"StackTrace es la traza de llamadas; Message es el texto descriptivo del error, un dato distinto."),
  sqr("¿Por qué escribir 'catch (Exception ex)' como único manejador en toda la aplicación se considera una mala práctica?","Porque oculta errores inesperados de programación y dificulta distinguir fallos recuperables de bugs reales",["Porque System.Exception no puede capturar errores de E/S","Porque el compilador lo prohíbe en proyectos modernos","Porque solo puede usarse una vez por archivo"],3,"Capturar la clase base genérica silencia cualquier tipo de error, incluidos bugs de programación que deberían fallar visiblemente; conviene capturar tipos específicos."),
 ]},
 {id:"m13-try-catch-finally",title:"try / catch / finally",summary:"try encierra código riesgoso, catch maneja excepciones de un tipo específico (deben ordenarse de más específico a más general), y finally se ejecuta siempre —haya o no excepción, incluso con un return dentro del try— salvo que el proceso termine abruptamente. 'throw;' relanza preservando el stack trace original; 'throw ex;' lo reinicia.",code:"try\n{\n    ProcesarArchivo();\n}\ncatch (FileNotFoundException ex)\n{\n    Console.WriteLine($\"No encontrado: {ex.Message}\");\n}\ncatch (Exception ex)\n{\n    Console.WriteLine($\"Error general: {ex.Message}\");\n}\nfinally\n{\n    Console.WriteLine(\"Limpieza\");\n}",questions:[
  sqr("¿Qué produce este código al compilar?","Error de compilación: un catch anterior ya captura todas las excepciones de este tipo o de un tipo superior",["Compila y siempre ejecuta el catch de FileNotFoundException","Compila y siempre ejecuta el catch de Exception","Compila pero nunca entra a ningún catch"],0,"El compilador rechaza (CS0160) un catch más específico colocado después de uno que ya cubre ese tipo; el orden debe ir de más específico a más general.","try { Leer(); }\ncatch (Exception ex) { Console.WriteLine(ex.Message); }\ncatch (FileNotFoundException ex) { Console.WriteLine(\"no existe\"); }"),
  sqr("¿Se ejecuta el bloque finally si el try termina exitosamente sin lanzar ninguna excepción?","Sí, finally siempre se ejecuta, con o sin excepción",["No, finally solo corre si hubo excepción","Solo si hay un catch presente","Solo si el try contiene un return"],1,"finally se ejecuta siempre al salir del try, independientemente de si hubo excepción, salvo terminación abrupta del proceso."),
  sqr("¿Qué imprime este método al ejecutarse?","\"finally\" y luego devuelve 1",["Solo devuelve 1 sin imprimir nada","Solo imprime \"finally\" sin devolver nada","Lanza una excepción de compilación por el return dentro del try"],2,"finally se ejecuta antes de que el método realmente retorne, aunque haya un return dentro del try; el valor 1 ya quedó determinado y se entrega después de correr finally.","static int Metodo()\n{\n    try { return 1; }\n    finally { Console.WriteLine(\"finally\"); }\n}"),
  sqr("¿Qué diferencia hay entre 'throw;' y 'throw ex;' dentro de un catch?","'throw;' preserva el stack trace original; 'throw ex;' lo reinicia como si la excepción se originara ahí",["Son exactamente equivalentes","'throw ex;' preserva el stack trace y 'throw;' lo reinicia","'throw;' solo funciona fuera de un catch"],3,"'throw;' relanza la excepción capturada conservando su stack trace original; 'throw ex;' sobrescribe el stack trace con la ubicación del throw ex."),
  sqr("Si un try tiene varios catch para distintos tipos, ¿cuántos catch se ejecutan cuando ocurre una excepción?","Como máximo uno: el primero, de arriba hacia abajo, cuyo tipo coincida",["Todos los catch cuyo tipo sea compatible","Ninguno si hay más de un catch","Todos, en orden, sin excepción"],0,"Los catch se evalúan en orden y solo se ejecuta el primero que coincida con el tipo (o supertipo) de la excepción lanzada."),
  sqr("¿Es válido escribir un bloque try/finally sin ningún catch?","Sí, es válido y se usa para garantizar limpieza sin capturar la excepción (que sigue propagándose)",["No, el compilador exige al menos un catch","Solo es válido dentro de métodos async","Solo es válido si el try no puede lanzar excepciones"],1,"try/finally sin catch es sintaxis válida: ejecuta la limpieza en finally y deja que la excepción continúe propagándose hacia el llamador."),
  sqr("¿Qué permite hacer la cláusula de filtro 'when' en un catch, como en 'catch (Exception ex) when (condición)'?","Capturar la excepción solo si la condición es verdadera; si es falsa, la excepción sigue propagándose como si ese catch no existiera",["Ejecutar el catch dos veces si la condición es verdadera","Ignorar la excepción silenciosamente si la condición es falsa","Forzar que el catch se ejecute siempre, evaluando la condición después"],2,"Un filtro 'when' evalúa una condición booleana; si es falsa, ese catch se descarta y se sigue buscando otro catch o se propaga la excepción."),
  sqr("Si dentro de un bloque catch se lanza una nueva excepción, ¿qué ocurre con el finally del mismo try/catch?","El finally igual se ejecuta antes de que la nueva excepción continúe propagándose",["El finally se omite porque ya hubo un catch","El finally se ejecuta dos veces","El programa termina sin ejecutar finally"],3,"finally se ejecuta siempre al desenrollar el bloque try/catch, incluso si el propio catch lanza una nueva excepción."),
  sqr("¿Qué excepción es conocida por no poder ser capturada de forma confiable por ningún try/catch y termina el proceso directamente?","StackOverflowException",["OutOfMemoryException siempre","InvalidOperationException","ArgumentException"],0,"Desde .NET Framework 2.0 en adelante (y en .NET moderno), StackOverflowException no puede capturarse; termina el proceso por diseño para evitar estado corrupto."),
  sqr("¿Qué trampa de entrevista hay sobre poner 'catch (Exception ex)' como primer y único catch de una cadena?","El compilador no lo prohíbe, pero vuelve inalcanzable cualquier catch más específico que se agregue después",["Es obligatorio hacerlo siempre en C#","Provoca un error de compilación inmediato","Hace que finally deje de ejecutarse"],1,"catch(Exception) es válido, pero al capturar cualquier tipo, cualquier catch más específico colocado después se vuelve código muerto y no compila."),
 ]},
 {id:"m13-custom-exceptions",title:"Crear excepciones propias",summary:"Una excepción personalizada se crea heredando de Exception (o de una subclase más específica), siguiendo la convención de nombrarla terminando en 'Exception' y proveyendo constructores que reenvíen a los de la clase base con ': base(message)' o ': base(message, innerException)'. Puede agregar propiedades propias para dar datos estructurados al llamador.",code:"public class SaldoInsuficienteException : Exception\n{\n    public decimal SaldoActual { get; }\n\n    public SaldoInsuficienteException(string mensaje, decimal saldoActual)\n        : base(mensaje)\n    {\n        SaldoActual = saldoActual;\n    }\n}",questions:[
  sqr("¿De qué debe derivar (directa o indirectamente) una excepción personalizada en C#?","De System.Exception",["De System.Object directamente sin pasar por Exception","De una interfaz IException","No requiere heredar de ninguna clase base"],0,"Toda excepción, incluidas las personalizadas, debe derivar de System.Exception para poder lanzarse con throw y capturarse con catch."),
  sqr("¿Qué convención de nombres siguen las clases de excepción en .NET?","Terminar el nombre con el sufijo 'Exception', por ejemplo SaldoInsuficienteException",["Empezar con el prefijo 'Err'","Usar siempre mayúsculas completas, como SALDOINSUFICIENTE","No tienen convención de nombres"],1,"La convención de .NET es que los tipos de excepción terminen en 'Exception' para identificarlos fácilmente."),
  sqr("En el constructor 'public SaldoInsuficienteException(string mensaje, decimal saldoActual) : base(mensaje)', ¿qué hace ': base(mensaje)'?","Invoca el constructor de Exception para inicializar la propiedad Message con ese texto",["Declara una variable local llamada base","Crea una nueva excepción anidada automáticamente","No hace nada si SaldoActual también se asigna"],2,"': base(mensaje)' llama al constructor heredado de Exception, que es quien establece la propiedad Message."),
  sqr("Si tienes catch para SaldoInsuficienteException y catch para Exception en el mismo try, ¿en qué orden deben declararse?","Primero el catch de SaldoInsuficienteException (más específico) y después el de Exception (más general)",["El orden es indiferente para el compilador y el runtime","Primero Exception y después SaldoInsuficienteException","Deben combinarse en un único catch con 'or'"],3,"Igual que con cualquier jerarquía de excepciones, el catch más específico debe ir antes que el más general, o el compilador rechaza el código."),
  sqr("¿Para qué sirve el parámetro innerException en un constructor como 'Exception(string message, Exception innerException)'?","Para preservar la excepción original que causó el error al envolverla en una nueva excepción de más alto nivel",["Para ignorar la excepción original","Para forzar que finally no se ejecute","Para convertir la excepción en un warning"],0,"innerException conserva la causa raíz cuando se relanza como un tipo distinto, ayudando a depurar la cadena completa de errores."),
  sqr("¿Es válido agregar propiedades adicionales, como SaldoActual, a una excepción personalizada?","Sí, y es una práctica común para exponer datos estructurados sobre el error, más allá del texto en Message",["No, Exception no permite agregar miembros nuevos","Solo si la propiedad es de tipo string","Solo si se marca con [Obsolete]"],1,"Las clases de excepción son clases normales: pueden tener propiedades propias que el código que captura la excepción puede leer directamente."),
  sqr("Si el código lanza 'throw new SaldoInsuficienteException(...)' y el llamador solo tiene 'catch (Exception ex)', ¿se captura la excepción?","Sí, porque SaldoInsuficienteException es (por herencia) también un Exception",["No, solo se captura con el tipo exacto declarado","Solo si se agrega [Serializable] a la clase","Solo si el catch declara 'catch (SaldoInsuficienteException ex)'"],2,"Por polimorfismo, un catch de un tipo base captura cualquier excepción derivada de ese tipo, incluidas las personalizadas."),
  sqr("¿Cuál es la guía actual de .NET sobre heredar de System.ApplicationException para excepciones propias?","Se recomienda heredar directamente de System.Exception; ApplicationException no aporta beneficio real y su uso está desaconsejado",["Es obligatorio heredar de ApplicationException","ApplicationException es la única clase base permitida para tipos públicos","ApplicationException reemplazó a Exception en .NET moderno"],1,"Aunque ApplicationException existió como convención histórica, la guía moderna de .NET recomienda derivar directamente de Exception."),
  sqr("¿Cuándo conviene crear una excepción personalizada en lugar de usar una genérica como InvalidOperationException?","Cuando representa una condición de negocio específica que el código llamador necesita distinguir y manejar de forma particular",["Siempre, nunca deben usarse las excepciones genéricas de .NET","Nunca, .NET prohíbe crear excepciones propias en apps de consola","Solo cuando el mensaje de error supera 100 caracteres"],3,"Las excepciones propias tienen sentido cuando el llamador necesita reaccionar distinto ante un error de dominio concreto, más allá de un mensaje de texto genérico."),
  sqr("¿Qué modificador de acceso debe tener normalmente una clase de excepción personalizada para que código externo pueda capturarla?","public",["private","internal siempre, sin excepciones","protected"],0,"Para que otro código (incluido otro ensamblado) pueda referenciar el tipo en un catch, la clase de excepción normalmente debe ser public."),
 ]},
 {id:"m13-file-directory",title:"File y Directory",summary:"File y Directory son clases estáticas de System.IO para operaciones simples de una sola vez (existe, crear, borrar, copiar, listar). FileInfo/DirectoryInfo son sus equivalentes basados en instancia, más eficientes cuando se repiten varias operaciones sobre la misma ruta. Directory.CreateDirectory crea automáticamente todas las carpetas intermedias que falten.",code:"if (!Directory.Exists(\"datos\"))\n{\n    Directory.CreateDirectory(\"datos\");\n}\n\nstring ruta = Path.Combine(\"datos\", \"clientes.txt\");\nif (File.Exists(ruta))\n{\n    File.Delete(ruta);\n}\n\nstring[] archivos = Directory.GetFiles(\"datos\", \"*.txt\");",questions:[
  sqr("¿Qué devuelve File.Exists(\"noexiste.txt\") si el archivo no existe?","false, sin lanzar ninguna excepción",["Lanza FileNotFoundException","Lanza IOException","null"],0,"File.Exists está diseñado para comprobar sin lanzar excepciones: simplemente devuelve false si el archivo no existe o la ruta no es accesible."),
  sqr("Si ninguna de las carpetas 'a', 'a/b' ni 'a/b/c' existe, ¿qué hace Directory.CreateDirectory(\"a/b/c\")?","Crea las tres carpetas intermedias necesarias en un solo llamado, sin error",["Lanza DirectoryNotFoundException porque faltan carpetas padre","Solo crea 'a' y falla en 'b' y 'c'","No hace nada si más de un nivel falta"],1,"Directory.CreateDirectory crea automáticamente toda la cadena de carpetas intermedias que no existan, similar a 'mkdir -p'."),
  sqr("¿Cuál es la diferencia principal entre la clase estática File y la clase FileInfo?","File expone métodos estáticos para operaciones puntuales; FileInfo es una instancia que cachea información y es más eficiente en operaciones repetidas sobre la misma ruta",["Son idénticas, File es solo un alias de FileInfo","FileInfo no puede leer ni escribir archivos","File solo funciona con archivos de texto y FileInfo con binarios"],2,"File hace comprobaciones de seguridad y resuelve la ruta en cada llamada estática; FileInfo, al ser una instancia, reutiliza esa información entre operaciones sucesivas sobre el mismo archivo."),
  sqr("¿Para qué sirve Path.Combine(\"datos\", \"clientes.txt\")?","Combina segmentos de ruta usando el separador correcto del sistema operativo, evitando concatenar strings manualmente",["Convierte una ruta relativa en absoluta siempre","Verifica que el archivo resultante exista","Cifra el nombre del archivo"],1,"Path.Combine une fragmentos de ruta con el separador correspondiente a la plataforma (\\ en Windows, / en Linux/macOS), evitando errores manuales."),
  sqr("Si el archivo destino ya existe y llamas a File.Copy(origen, destino) sin indicar sobrescritura, ¿qué ocurre?","Lanza IOException porque el destino ya existe",["Sobrescribe el destino silenciosamente por defecto","Crea un archivo con sufijo automático como \"(1)\"","No hace nada y retorna false"],2,"Por defecto, File.Copy(origen, destino) sin el parámetro overwrite=true lanza IOException si el archivo destino ya existe."),
  sqr("¿Qué diferencia clave hay entre Directory.GetFiles y Directory.EnumerateFiles?","GetFiles devuelve un arreglo completo cargado de una vez; EnumerateFiles devuelve resultados de forma perezosa (streaming), útil para carpetas muy grandes",["Son exactamente equivalentes en todo sentido","EnumerateFiles no admite patrones de búsqueda","GetFiles busca recursivamente por defecto y EnumerateFiles no"],0,"GetFiles espera a tener todos los resultados antes de devolver el arreglo; EnumerateFiles permite empezar a procesar archivos antes de terminar de enumerar toda la carpeta."),
  sqr("¿Qué ocurre si llamas a File.Delete(\"noexiste.txt\") sobre un archivo que no existe?","No lanza excepción: es una operación sin efecto (no-op)",["Lanza FileNotFoundException","Lanza UnauthorizedAccessException","Crea el archivo vacío y luego lo elimina"],3,"A diferencia de lo que muchos esperan, File.Delete no lanza excepción si el archivo ya no existe; simplemente no hace nada."),
  sqr("Por defecto, ¿Directory.GetFiles(\"datos\", \"*.txt\") busca también en subcarpetas de \"datos\"?","No, por defecto solo lista archivos del nivel superior indicado (no es recursivo)",["Sí, siempre busca recursivamente en todas las subcarpetas","Solo si el patrón termina en \"/**\"","Solo en sistemas Linux"],0,"Sin especificar SearchOption.AllDirectories, GetFiles/EnumerateFiles solo examinan el directorio indicado, no sus subcarpetas."),
  sqr("¿Cómo se indica a Directory.GetFiles que busque también en todas las subcarpetas?","Pasando SearchOption.AllDirectories como tercer argumento",["Usando un patrón como \"**/*.txt\"","Es el comportamiento por defecto, no requiere nada extra","Llamando a Directory.GetFilesRecursive"],1,"Directory.GetFiles(ruta, patron, SearchOption.AllDirectories) habilita la búsqueda recursiva en todas las subcarpetas."),
  sqr("Si \"datos\" es en realidad una carpeta (no un archivo), ¿qué devuelve File.Exists(\"datos\")?","false, porque File.Exists comprueba específicamente archivos, no carpetas",["true, porque la ruta existe en el sistema","Lanza UnauthorizedAccessException","Lanza una excepción de tipo ArgumentException"],2,"File.Exists solo devuelve true si la ruta apunta a un archivo existente; para una carpeta con ese nombre, devuelve false (hay que usar Directory.Exists)."),
 ]},
 {id:"m13-read-write-text",title:"Leer y escribir texto",summary:"File.ReadAllText/WriteAllText trabajan con el contenido completo de un archivo como un solo string; File.ReadAllLines/WriteAllLines usan arreglos de líneas; File.AppendAllText agrega texto sin borrar lo existente. Todas tienen versión asíncrona (…Async) que devuelve Task y debe esperarse con await.",code:"File.WriteAllText(\"nota.txt\", \"Hola mundo\");\nstring contenido = File.ReadAllText(\"nota.txt\");\n\nFile.AppendAllText(\"nota.txt\", \"\\nSegunda línea\");\n\nstring[] lineas = File.ReadAllLines(\"nota.txt\");",questions:[
  sqr("Si \"nota.txt\" ya existía con contenido previo, ¿qué hace File.WriteAllText(\"nota.txt\", \"Hola mundo\")?","Sobrescribe por completo el contenido anterior del archivo con el nuevo texto",["Agrega el nuevo texto al final, conservando lo anterior","Lanza IOException porque el archivo ya existe","Crea un nuevo archivo con sufijo automático"],0,"WriteAllText trunca y reemplaza todo el contenido existente por defecto; para agregar sin borrar se usa AppendAllText."),
  sqr("¿Qué hace File.AppendAllText(\"nota.txt\", texto) si el archivo no existe todavía?","Crea el archivo nuevo con ese texto, igual que si fuera la primera escritura",["Lanza FileNotFoundException porque el archivo no existe","No hace nada silenciosamente","Lanza DirectoryNotFoundException siempre"],1,"AppendAllText crea el archivo si no existe; si existe, agrega el texto al final sin borrar el contenido previo."),
  sqr("¿Qué tipo de dato devuelve File.ReadAllLines(\"nota.txt\")?","string[], un arreglo con una línea de texto por elemento, sin los caracteres de salto de línea",["Un único string con todo el contenido","IEnumerable<byte> con los bytes crudos","StreamReader listo para seguir leyendo"],2,"ReadAllLines separa el archivo por líneas y devuelve un arreglo de strings, cada uno sin el carácter de fin de línea."),
  sqr("¿Qué tipo de dato devuelve File.ReadAllText(\"nota.txt\")?","string, con todo el contenido del archivo en un solo valor, incluyendo saltos de línea internos",["string[] con una línea por elemento","byte[] con el contenido binario","Stream abierto sobre el archivo"],3,"ReadAllText concatena todo el archivo en un único string; a diferencia de ReadAllLines, no lo separa en líneas."),
  sqr("¿Qué ocurre al llamar File.ReadAllText(\"noexiste.txt\") si el archivo no existe?","Lanza FileNotFoundException",["Devuelve string.Empty","Devuelve null","Crea el archivo vacío automáticamente y lo lee"],0,"A diferencia de File.Exists, los métodos de lectura como ReadAllText sí lanzan excepción (FileNotFoundException) si el archivo no existe."),
  sqr("¿Cuál es el equivalente asíncrono de File.ReadAllText?","File.ReadAllTextAsync, que devuelve Task<string> y debe esperarse con await",["File.ReadAllText ya es asíncrono por defecto","File.ReadTextParallel","No existe versión asíncrona para lectura de texto"],1,"File.ReadAllTextAsync es la versión asíncrona equivalente, pensada para no bloquear el hilo mientras se hace E/S."),
  sqr("Si no se especifica una codificación, ¿qué encoding usa File.WriteAllText por defecto en .NET moderno?","UTF-8 (sin BOM)",["ASCII de 7 bits","UTF-16 Little Endian","Latin1 (ISO-8859-1)"],2,"Los métodos de File en .NET moderno usan UTF-8 sin BOM como codificación de texto por defecto cuando no se especifica otra."),
  sqr("¿Qué tipo de parámetro acepta File.WriteAllLines para el contenido a escribir?","Un IEnumerable<string> (por ejemplo un arreglo o una lista), escribiendo cada elemento como una línea separada",["Un único string con saltos de línea manuales","Un Stream ya abierto","Un objeto JSON serializado"],3,"WriteAllLines recibe una colección de strings y escribe cada elemento en su propia línea, agregando el separador de línea entre ellos."),
  sqr("Para un archivo de varios gigabytes, ¿por qué usar StreamReader en lugar de File.ReadAllText?","Porque StreamReader permite leer de forma incremental (por ejemplo línea por línea) sin cargar el archivo entero en memoria",["Porque StreamReader es siempre más rápido en archivos pequeños","Porque File.ReadAllText no puede leer archivos de texto plano","Porque StreamReader no requiere manejo de excepciones"],0,"File.ReadAllText carga todo el archivo en memoria de una vez; para archivos muy grandes eso puede agotar memoria, mientras StreamReader procesa por partes."),
  sqr("Si la carpeta \"logs\" no existe, ¿qué ocurre al llamar File.AppendAllText(\"logs/app.txt\", texto)?","Lanza DirectoryNotFoundException, porque AppendAllText no crea carpetas faltantes automáticamente",["Crea automáticamente la carpeta \"logs\" y el archivo","No hace nada de forma silenciosa","Escribe el archivo en la carpeta actual ignorando \"logs/\""],1,"A diferencia de Directory.CreateDirectory, los métodos de File no crean carpetas intermedias faltantes; si la carpeta padre no existe, lanzan DirectoryNotFoundException."),
 ]},
 {id:"m13-streams",title:"Streams",summary:"Stream es la abstracción para E/S secuencial de bytes (FileStream, MemoryStream, NetworkStream). StreamReader/StreamWriter envuelven un Stream para leer/escribir texto agregando buffering interno. Todos implementan IDisposable: hay que liberarlos (using) para vaciar el buffer y cerrar el recurso del sistema operativo; si no, se puede perder texto que quedó solo en el buffer.",code:"using (var writer = new StreamWriter(\"log.txt\", append: true))\n{\n    writer.WriteLine(\"Evento registrado\");\n} // Dispose() vacía el buffer y cierra el archivo automáticamente",questions:[
  sqr("¿Qué garantiza el bloque 'using' sobre un StreamWriter?","Que Dispose() se llame automáticamente al salir del bloque, incluso si ocurre una excepción, vaciando el buffer y liberando el archivo",["Que el archivo se abra en modo solo lectura","Que las escrituras sean síncronas obligatoriamente","Que no puedan ocurrir excepciones dentro del bloque"],0,"'using' garantiza la llamada a Dispose() al salir del bloque (normal o por excepción), lo cual vacía el buffer interno del writer y cierra el handle del archivo."),
  sqr("Si escribes con StreamWriter y el proceso termina abruptamente sin llamar Dispose/Close/Flush, ¿qué riesgo hay?","Que datos ya \"escritos\" con WriteLine queden solo en el buffer en memoria y nunca lleguen al disco",["Ninguno, StreamWriter siempre escribe cada carácter de inmediato al disco","El archivo queda corrupto de forma irreversible siempre","El sistema operativo fuerza el flush automáticamente cada segundo"],1,"StreamWriter usa un buffer interno por rendimiento; sin Flush/Dispose, ese contenido puede perderse si el proceso termina antes de vaciarlo."),
  sqr("¿Qué diferencia hay entre FileStream y StreamWriter?","FileStream trabaja con bytes crudos; StreamWriter es una capa de más alto nivel que codifica texto a bytes sobre un Stream subyacente",["Son exactamente lo mismo con nombres distintos","StreamWriter no puede escribir en archivos, solo en memoria","FileStream solo sirve para leer, nunca para escribir"],2,"FileStream opera a nivel de bytes; StreamWriter añade la conversión de caracteres (Encoding) a bytes y buffering de texto encima de un Stream."),
  sqr("Con 'new StreamWriter(\"log.txt\", append: true)', si el archivo ya existía, ¿qué habría pasado si en cambio se usara append: false (el valor por defecto)?","El archivo existente se trunca/sobrescribe por completo al abrirlo",["Se agrega el texto al final igualmente","Lanza IOException porque el archivo ya existe","No se puede escribir hasta borrar el archivo manualmente"],3,"Con append en false (el valor por defecto de otros constructores), StreamWriter trunca el archivo existente al abrirlo, perdiendo su contenido previo."),
  sqr("¿Qué interfaz implementan Stream, StreamReader, StreamWriter y FileStream, que obliga a liberarlos correctamente?","IDisposable",["IEnumerable","ICloneable","IComparable"],0,"Todos ellos implementan IDisposable porque retienen recursos no administrados (handles del sistema operativo, buffers) que deben liberarse explícitamente."),
  sqr("¿Para qué se usa típicamente un MemoryStream en lugar de un FileStream?","Para manipular datos como un stream de bytes completamente en memoria, sin tocar el sistema de archivos",["Para acceder más rápido a archivos grandes en disco","Para forzar que los datos persistan tras cerrar la aplicación","Para comprimir automáticamente cualquier archivo"],1,"MemoryStream ofrece la misma API de Stream pero respaldada por un arreglo en memoria, útil para construir o transformar datos sin E/S de disco."),
  sqr("¿Qué hace Stream.Flush()?","Fuerza que cualquier dato retenido en el buffer se escriba de inmediato hacia el destino, sin necesariamente cerrar el stream",["Cierra el stream y libera el archivo","Borra todo el contenido escrito hasta el momento","Reinicia la posición del stream al principio"],2,"Flush() vacía el buffer interno hacia el destino subyacente sin cerrar el stream, a diferencia de Dispose/Close que además liberan el recurso."),
  sqr("¿Qué diferencia hay entre 'using (var writer = ...) { ... }' y 'using var writer = ...;' (using-declaration de C# 8+)?","La using-declaration difiere la llamada a Dispose() hasta el final del ámbito que la contiene (por ejemplo, el método), en lugar de un bloque explícito",["No hay ninguna diferencia funcional","La using-declaration nunca llama a Dispose()","El bloque using clásico ya no está soportado en C# moderno"],1,"La using-declaration sin llaves sigue garantizando Dispose(), pero al final del ámbito envolvente (el método, por ejemplo) en vez de un bloque delimitado explícitamente."),
  sqr("Si un FileStream ya está abierto para escritura sobre \"log.txt\" con el modo de uso compartido por defecto, ¿qué ocurre si otro proceso intenta abrirlo también para escritura al mismo tiempo?","Normalmente lanza IOException indicando que el archivo está en uso por otro proceso",["Ambos procesos pueden escribir simultáneamente sin ningún error","El segundo proceso espera automáticamente sin timeout","Los datos de ambos procesos se combinan automáticamente"],3,"Por defecto, el acceso compartido de FileStream no permite que dos escrituras concurrentes convivan libremente; el segundo intento suele fallar con IOException."),
  sqr("Al hacer 'new StreamWriter(new FileStream(...))' y luego Dispose() solo sobre el StreamWriter, ¿es necesario además hacer Dispose() manualmente sobre el FileStream interno?","No, al hacer Dispose() del StreamWriter también se libera (por defecto) el Stream subyacente que envuelve",["Sí, siempre hay que liberar ambos por separado o se filtra el handle","No, pero entonces el FileStream queda abierto para siempre","Solo es necesario en Linux, no en Windows"],0,"Por defecto, disponer el wrapper (StreamWriter) también dispone el Stream que envuelve, salvo que se use explícitamente el overload que indica lo contrario (leaveOpen)."),
 ]},
 {id:"m13-json",title:"JSON básico",summary:"System.Text.Json.JsonSerializer.Serialize/Deserialize convierten objetos a/desde JSON. Por defecto, Serialize conserva los nombres de propiedad de C# tal cual (normalmente PascalCase) y Deserialize compara nombres de forma sensible a mayúsculas/minúsculas. JsonSerializerOptions permite indentar, cambiar la política de nombres a camelCase o volverlo insensible a mayúsculas; [JsonPropertyName] y [JsonIgnore] personalizan propiedades individuales.",code:"public record Persona(string Nombre, int Edad);\n\nvar persona = new Persona(\"Ana\", 30);\nstring json = JsonSerializer.Serialize(persona);\n// {\"Nombre\":\"Ana\",\"Edad\":30}\n\nPersona restaurada = JsonSerializer.Deserialize<Persona>(json)!;",questions:[
  sqr("¿Qué produce JsonSerializer.Serialize(persona) por defecto, dado un record con propiedades Nombre y Edad en PascalCase?","Un JSON con las claves en PascalCase tal cual (\"Nombre\", \"Edad\"), sin convertir automáticamente a camelCase",["Un JSON con las claves en camelCase (\"nombre\", \"edad\") automáticamente","Un JSON con todas las claves en minúsculas sin excepción","Lanza una excepción porque los records no son serializables"],0,"Sin configurar una PropertyNamingPolicy, System.Text.Json conserva los nombres de las propiedades de C# exactamente como están declarados."),
  sqr("Si el JSON de entrada tiene la clave \"nombre\" en minúsculas pero la propiedad en C# se llama \"Nombre\" (PascalCase), ¿la asocia JsonSerializer.Deserialize<Persona> por defecto?","No, por defecto la comparación de nombres es sensible a mayúsculas/minúsculas (PropertyNameCaseInsensitive vale false), así que no coincide",["Sí, siempre es insensible a mayúsculas/minúsculas por defecto","Solo coincide si la clase es una class y no un record","Lanza JsonException inmediatamente ante cualquier diferencia de casing"],1,"El valor por defecto de JsonSerializerOptions.PropertyNameCaseInsensitive es false; hay que activarlo explícitamente para tolerar diferencias de mayúsculas/minúsculas."),
  sqr("¿Cómo se configura JsonSerializer.Serialize para producir JSON indentado (\"pretty printed\")?","Pasando JsonSerializerOptions con WriteIndented = true",["Es el comportamiento por defecto sin configurar nada","Usando el método JsonSerializer.SerializePretty","Agregando [JsonIndented] sobre la clase"],2,"WriteIndented = true en JsonSerializerOptions produce salida legible con saltos de línea y sangría."),
  sqr("¿Qué atributo se usa para que una propiedad de C# se serialice/deserialice con un nombre distinto en el JSON?","[JsonPropertyName(\"nombre_json\")]",["[JsonRename(\"nombre_json\")]","[JsonAlias(\"nombre_json\")]","[JsonKey(\"nombre_json\")]"],3,"[JsonPropertyName] indica explícitamente el nombre de la clave JSON asociada a esa propiedad, sin importar el nombre del miembro en C#."),
  sqr("¿Qué atributo evita que una propiedad de C# se incluya al serializar a JSON?","[JsonIgnore]",["[JsonExclude]","[NonSerialized] únicamente","[JsonSkip]"],0,"[JsonIgnore], de System.Text.Json.Serialization, excluye la propiedad tanto de la serialización como (por defecto) de la deserialización."),
  sqr("¿Qué ocurre al llamar JsonSerializer.Deserialize<Persona>(json) si el string 'json' no es JSON válido?","Lanza una excepción de tipo JsonException",["Devuelve null silenciosamente","Devuelve una instancia de Persona con todos los campos en su valor por defecto","Ignora el error y devuelve un string vacío"],1,"Un JSON malformado hace que Deserialize lance JsonException en lugar de devolver un resultado parcial o nulo."),
  sqr("¿En qué namespace se encuentra la clase JsonSerializer usada en el ejemplo?","System.Text.Json",["System.Json","Newtonsoft.Json","System.Runtime.Serialization.Json"],2,"JsonSerializer pertenece a System.Text.Json, la API de JSON integrada en .NET desde .NET Core 3.0 (distinta de la librería externa Newtonsoft.Json)."),
  sqr("¿Puede System.Text.Json serializar y deserializar directamente un C# record como Persona, sin conversión manual?","Sí, los records se tratan igual que las clases: se serializan sus propiedades públicas y se pueden deserializar usando el constructor que coincide",["No, los records deben convertirse primero a Dictionary","Solo si el record implementa IJsonSerializable","Solo puede serializar records, nunca deserializarlos"],3,"System.Text.Json soporta records de forma nativa, incluyendo el uso del constructor posicional para reconstruir la instancia al deserializar."),
  sqr("¿Cómo se activa la conversión automática a camelCase al serializar?","JsonSerializerOptions { PropertyNamingPolicy = JsonNamingPolicy.CamelCase }",["Es el comportamiento por defecto en cualquier proyecto .NET","JsonSerializerOptions { CamelCase = true }","Renombrando manualmente cada propiedad de C# a camelCase"],0,"PropertyNamingPolicy = JsonNamingPolicy.CamelCase convierte automáticamente los nombres PascalCase de C# a camelCase en el JSON de salida."),
  sqr("Por defecto, ¿JsonSerializer.Serialize incluye los campos privados (no las propiedades) de una clase?","No, por defecto solo serializa propiedades públicas legibles; los campos (públicos o privados) no se incluyen salvo configuración explícita",["Sí, incluye automáticamente todos los campos privados","Solo si la clase tiene un constructor sin parámetros","Sí, pero solo si están marcados con 'readonly'"],1,"El comportamiento por defecto de System.Text.Json serializa propiedades públicas; ni los campos privados ni, por defecto, los campos públicos se incluyen sin configuración adicional."),
 ]},
 {id:"m13-challenge",title:"Reto de persistencia",summary:"Reto integrador: combina excepciones, try/catch/finally, File/Directory y JSON para cargar y guardar configuración de forma robusta, distinguiendo un archivo ausente (se usa un valor por defecto) de un archivo corrupto (se relanza como una excepción de dominio con la causa original preservada).",code:"public static Config CargarConfiguracion(string ruta)\n{\n    try\n    {\n        string json = File.ReadAllText(ruta);\n        return JsonSerializer.Deserialize<Config>(json) ?? new Config();\n    }\n    catch (FileNotFoundException)\n    {\n        return new Config();\n    }\n    catch (JsonException ex)\n    {\n        throw new ConfigInvalidaException(\"El archivo de configuración está corrupto\", ex);\n    }\n}",questions:[
  sqr("En CargarConfiguracion, si el archivo indicado por 'ruta' no existe, ¿qué devuelve el método?","Una nueva instancia Config() con valores por defecto, sin propagar ninguna excepción",["Lanza ConfigInvalidaException","Lanza FileNotFoundException sin capturarla","Devuelve null"],0,"El catch específico de FileNotFoundException intercepta ese caso puntual y responde con una configuración por defecto en lugar de fallar."),
  sqr("Si el archivo existe pero su contenido no es JSON válido, ¿qué hace el método?","Lanza ConfigInvalidaException, envolviendo la JsonException original como InnerException",["Devuelve new Config() igual que si el archivo no existiera","Devuelve null silenciosamente","Vuelve a intentar leer el archivo automáticamente"],1,"El catch de JsonException relanza una excepción de dominio (ConfigInvalidaException) preservando la causa original mediante el parámetro innerException."),
  sqr("¿Por qué se pasa 'ex' como segundo argumento al construir ConfigInvalidaException?","Para preservar la excepción original (JsonException) como InnerException y no perder información de la causa raíz",["Porque es obligatorio por sintaxis aunque no se use",'Para forzar que "ex" se imprima dos veces en consola',"Para cancelar automáticamente la operación en curso"],2,"Pasar la excepción original como innerException mantiene la cadena de causalidad completa, útil para depurar el problema real detrás del error de dominio."),
  sqr("Si JsonSerializer.Deserialize<Config>(json) devuelve null (por ejemplo, si json es el texto \"null\"), ¿qué produce la expresión '?? new Config()'?","Devuelve una nueva instancia Config() con valores por defecto en lugar de propagar null",["Lanza NullReferenceException","Devuelve null de todas formas","Lanza ArgumentNullException"],3,"El operador ?? sustituye un resultado null de Deserialize por una nueva Config(), evitando que el método retorne null."),
  sqr("Si dentro del try se lanzara una UnauthorizedAccessException (por permisos del archivo), y no hay un catch para ese tipo, ¿qué ocurre?","La excepción se propaga sin ser capturada por este método, ya que solo hay catch para FileNotFoundException y JsonException",["Se captura silenciosamente igual que FileNotFoundException","Se convierte automáticamente en ConfigInvalidaException","El método la ignora y retorna new Config()"],0,"Solo los tipos explícitamente declarados en los catch (FileNotFoundException y JsonException) se manejan aquí; cualquier otro tipo de excepción sigue propagándose hacia el llamador."),
  sqr("¿Qué diferencia práctica hay entre capturar FileNotFoundException específicamente (como aquí) y capturar Exception de forma genérica para todo el método?","Capturar el tipo específico permite dar una respuesta distinta según la causa real (archivo ausente vs. JSON corrupto), en vez de tratar todos los errores igual",["No hay ninguna diferencia observable en tiempo de ejecución","Exception genérico se ejecuta más rápido en todos los casos","FileNotFoundException no puede combinarse con otro catch en el mismo try"],1,"Distinguir por tipo permite decisiones de negocio distintas: un archivo ausente es recuperable con un valor por defecto, mientras que JSON corrupto amerita una excepción de dominio explícita."),
  sqr("Si se quisiera además garantizar que un mensaje 'Intento de carga finalizado' se registre siempre, sin importar si hubo éxito o excepción, ¿qué bloque agregarías?","Un bloque finally con esa línea de registro, ya que se ejecuta siempre al salir del try/catch",["Otro catch adicional para Exception genérica al final","Repetir la línea de registro en cada catch y también después del try, fuera de cualquier bloque","Convertir todo el método en async void"],2,"finally es la herramienta específica para código de limpieza/registro que debe ejecutarse en todos los caminos de salida, con o sin excepción."),
  sqr("¿Qué tipo de excepción esperarías que capture 'catch (JsonException ex)' si el archivo contiene el texto \"{ esto no es json\" (mal formado)?","JsonException, lanzada por JsonSerializer.Deserialize al no poder interpretar el contenido como JSON válido",["FileNotFoundException, porque el archivo técnicamente no es válido","ArgumentNullException","InvalidCastException"],3,"Un JSON mal formado hace que Deserialize falle con JsonException, que es exactamente el tipo capturado en ese bloque."),
  sqr("¿Qué ventaja tiene declarar el método como 'public static Config CargarConfiguracion(string ruta)' en lugar de una versión async equivalente para este escenario simple de un archivo pequeño?","Simplicidad: evita la sobrecarga de manejar Task/await cuando la operación de E/S es puntual y rápida; en escenarios con mucha E/S concurrente sí convendría la versión async",["Las versiones síncronas de E/S siempre son más rápidas que las asíncronas en cualquier escenario","File.ReadAllText no tiene una versión asíncrona disponible","Una versión async no podría lanzar excepciones"],0,"Para una carga puntual y simple, un método síncrono es válido y más simple; async I/O brinda más beneficio cuando hay múltiples operaciones concurrentes o se ejecuta en un contexto donde bloquear el hilo es costoso (por ejemplo, UI o servidores con alta concurrencia)."),
  sqr("Si se llama CargarConfiguracion(ruta) dos veces seguidas con la misma ruta a un archivo que sí existe y es válido, ¿qué se puede afirmar sobre el resultado?","Cada llamada vuelve a leer el archivo y deserializarlo desde cero, sin caché automático entre llamadas",["La segunda llamada usa un valor cacheado automáticamente por JsonSerializer","La segunda llamada lanza excepción porque el archivo ya fue leído antes","File.ReadAllText bloquea el archivo permanentemente tras la primera lectura"],1,"El método no implementa ningún tipo de caché: cada invocación abre, lee y deserializa el archivo nuevamente de forma independiente."),
 ]},
 {id:"m14-task",title:"Task y Task<T>",summary:"Task representa una operación asíncrona sin valor de retorno; Task<T> representa una que produce un resultado de tipo T al completarse. Task.Run encola el trabajo en el thread pool y lo inicia de inmediato ('caliente'); en cambio, 'new Task(...)' crea una tarea 'fría' que no corre hasta llamar Start(). Acceder a .Result bloquea el hilo actual hasta que la tarea termine.",code:"Task<int> tarea = Task.Run(() =>\n{\n    Thread.Sleep(1000);\n    return 42;\n});\n\nint resultado = await tarea;\nConsole.WriteLine(resultado);",questions:[
  sqr("¿Cuál es la diferencia fundamental entre Task y Task<T>?","Task representa una operación asíncrona sin resultado; Task<T> representa una que produce un valor de tipo T al completarse",["Task<T> siempre es más lento que Task","Task solo puede usarse con métodos async void","No hay ninguna diferencia real entre ambos"],0,"Task modela 'la operación terminó (o falló)' sin dato asociado; Task<T> añade un resultado tipado accesible vía .Result o await."),
  sqr("¿Qué hace Task.Run(() => { ... })?","Encola el delegado para ejecutarse en un hilo del thread pool y devuelve de inmediato un Task que representa ese trabajo ya iniciado",["Ejecuta el delegado de forma síncrona en el hilo actual y bloquea hasta terminar","Crea una tarea 'fría' que requiere llamar Start() manualmente","Solo funciona si el delegado es async"],1,"Task.Run programa el trabajo en el thread pool de inmediato ('caliente'); el llamador recibe el Task y puede seguir ejecutando otro código mientras tanto."),
  sqr("En 'int resultado = tarea.Result;' (en vez de await), si la tarea todavía no terminó, ¿qué ocurre?","El hilo actual se bloquea sincrónicamente hasta que la tarea complete",["Lanza una excepción inmediatamente porque la tarea no terminó","Devuelve el valor por defecto de int (0) mientras tanto","Cancela automáticamente la tarea en curso"],2,"Acceder a .Result antes de que la tarea complete bloquea el hilo llamador, a diferencia de await que libera el hilo mientras espera."),
  sqr("Si escribes 'var t = new Task(() => Console.WriteLine(\"hola\"));' y nunca llamas a t.Start(), ¿qué ocurre?","El delegado nunca se ejecuta; la tarea queda en estado Created para siempre (tarea 'fría')",["Se ejecuta automáticamente en cuanto el runtime tiene un hilo libre","Se ejecuta de inmediato de forma síncrona en la misma línea","Lanza una excepción al finalizar el programa por la tarea sin iniciar"],3,"A diferencia de Task.Run, el constructor 'new Task(...)' crea una tarea fría que solo comienza a ejecutarse tras invocar Start() explícitamente."),
  sqr("¿Para qué sirve Task.CompletedTask?","Es un Task ya completado y cacheado, útil para devolver de un método async-compatible que en realidad no necesita hacer ninguna espera real",["Es un Task que nunca podrá completarse","Cancela cualquier otra tarea en ejecución","Convierte automáticamente un método en async void"],0,"Task.CompletedTask evita crear una nueva instancia de Task para el caso común de 'ya terminé', sin resultado asociado."),
  sqr("Inmediatamente después de que Task.Run(...) devuelve el Task, ¿en qué estado se encuentra típicamente esa tarea?","Ya en ejecución o encolada para ejecutarse (no en estado Created 'frío' como con 'new Task')",["Siempre en estado Created, igual que 'new Task'","Siempre ya completada (RanToCompletion)","Siempre en estado Canceled hasta que se le indique lo contrario"],1,"Task.Run programa el trabajo de inmediato en el thread pool; el Task devuelto ya está 'caliente', a diferencia de una tarea creada con 'new Task(...)'."),
  sqr("¿Qué hace Task.Delay(1000) en comparación con Thread.Sleep(1000)?","Task.Delay produce un Task que se completa tras el tiempo indicado sin bloquear ningún hilo mientras tanto; Thread.Sleep bloquea el hilo actual por completo durante ese tiempo",["Ambos bloquean el hilo actual exactamente de la misma forma","Task.Delay ejecuta el código inmediatamente, ignorando el tiempo indicado","Thread.Sleep es asíncrono y Task.Delay es síncrono"],2,"Task.Delay es la alternativa no bloqueante pensada para usarse con await; Thread.Sleep bloquea físicamente el hilo que lo ejecuta durante todo el intervalo."),
  sqr("Al hacer 'await tarea' donde tarea es Task<int>, ¿qué tipo tiene la expresión resultante?","int (el resultado ya desempaquetado), no Task<int>",["Task<int>, el propio objeto tarea","object, requiere un cast explícito después","void, no se puede asignar a una variable"],3,"await 'desenvuelve' un Task<T>, dando directamente un valor de tipo T; para obtener el Task<int> original no se usa await."),
  sqr("Si haces await dos veces sobre la misma variable Task<int> ya completada, ¿qué sucede la segunda vez?","Devuelve inmediatamente el mismo resultado cacheado, sin volver a ejecutar el trabajo original",["Ejecuta el trabajo nuevamente desde cero","Lanza InvalidOperationException por reutilizar la tarea","Devuelve el valor por defecto de int en la segunda espera"],0,"Un Task completado guarda su resultado (o su excepción); esperarlo múltiples veces simplemente devuelve ese resultado cacheado sin reejecutar el trabajo."),
  sqr("Si la tarea de Task.Run falla internamente (lanza una excepción dentro del delegado) y luego accedes a tarea.Result, ¿qué tipo de excepción recibes exactamente?","AggregateException, que envuelve la excepción original en su propiedad InnerException/InnerExceptions",["La excepción original sin envolver, igual que con await","InvalidOperationException genérica sin relación con el error real","No se lanza ninguna excepción, .Result devuelve el valor por defecto"],1,"Acceder a .Result (o .Wait()) sobre una tarea fallida envuelve la excepción original en AggregateException; en cambio, await la desenvuelve y relanza directamente el tipo original."),
 ]},
 {id:"m14-async-await",title:"async y await",summary:"'async' marca un método que puede usar 'await' dentro de su cuerpo; el compilador lo transforma en una máquina de estados. 'await' suspende la ejecución del método hasta que la tarea esperada complete, sin bloquear el hilo que lo invoca, y libera ese hilo mientras tanto. Los tipos de retorno válidos son Task, Task<T>, ValueTask/ValueTask<T> y void (este último solo recomendable para manejadores de eventos).",code:"public static async Task<string> ObtenerSaludoAsync()\n{\n    await Task.Delay(500);\n    return \"Hola\";\n}\n\nstring saludo = await ObtenerSaludoAsync();\nConsole.WriteLine(saludo);",questions:[
  sqr("Mientras se ejecuta 'await Task.Delay(500)' dentro del método, ¿qué le sucede al hilo que estaba ejecutando ObtenerSaludoAsync?","Se libera para hacer otro trabajo; no queda bloqueado esperando el delay",["Queda bloqueado sin poder hacer nada más hasta que pasen los 500ms","Se destruye permanentemente","Entra en un bucle de espera activa (busy-wait) consumiendo CPU"],0,"await no bloquea el hilo: la ejecución del método se suspende y el hilo queda libre para otras tareas hasta que la operación esperada complete."),
  sqr("Además de void, ¿cuáles son los tipos de retorno válidos y recomendados para un método async que produce o no un resultado?","Task (sin resultado) y Task<T> (con resultado de tipo T), o sus variantes ValueTask/ValueTask<T>",["Solo void, es el único tipo permitido","int y string únicamente","IEnumerable<T> obligatoriamente"],1,"Un método async puede devolver Task, Task<T>, ValueTask, ValueTask<T>, o void (este último solo aceptable para manejadores de eventos)."),
  sqr("¿Qué ocurre si escribes un método marcado 'async Task' pero nunca usas 'await' dentro de su cuerpo?","Compila, mostrando la advertencia CS1998, y el método se ejecuta de forma esencialmente síncrona hasta completarse de inmediato",["Es un error de compilación obligatorio","El método se ejecuta indefinidamente sin terminar nunca","Se convierte automáticamente en 'async void'"],2,"El compilador permite un 'async' sin await interno (con advertencia CS1998), pero pierde el propósito de la asincronía: se ejecuta sincrónicamente y el Task resultante ya está completado al retornar."),
  sqr("¿Es válido en C# moderno declarar 'static async Task Main()' como punto de entrada de una aplicación de consola?","Sí, desde C# 7.1 se admite un método Main asíncrono como punto de entrada",["No, Main nunca puede ser async","Solo es válido si el proyecto usa top-level statements","Solo es válido en proyectos ASP.NET, no en consola"],3,"C# 7.1 introdujo soporte para 'async Task Main()' (y variantes con args/int), permitiendo usar await directamente en el punto de entrada."),
  sqr("¿Qué genera el compilador de C# a partir del cuerpo de un método async?","Una máquina de estados que gestiona la suspensión y reanudación de la ejecución en cada punto await",["Un nuevo hilo del sistema operativo por cada await","Código idéntico al de un método síncrono normal, sin cambios","Una clase que implementa IEnumerable"],0,"El compilador transforma internamente el método async en una máquina de estados que captura el contexto necesario para reanudar la ejecución tras cada await."),
  sqr("Si 'await tarea;' se ejecuta sobre una tarea que ya estaba completada en ese momento, ¿qué ocurre respecto a la suspensión del método?","Puede continuar sin una suspensión real perceptible, ya que no hay nada por esperar",["Siempre fuerza una suspensión y cambio de hilo, esté completada o no","Lanza una excepción por esperar una tarea ya terminada","El resultado se descarta y se reintenta la operación"],1,"Si la tarea ya completó, el await puede seguir de forma prácticamente síncrona sin una suspensión real, aunque sigue siendo válido el mismo mecanismo de await."),
  sqr("¿Cuál es la diferencia entre escribir 'var t = ObtenerSaludoAsync();' (sin await) y 'var s = await ObtenerSaludoAsync();'?","Sin await obtienes el objeto Task<string> que representa la operación aún en curso; con await obtienes directamente el string ya calculado, y el método espera antes de continuar",["Son estrictamente equivalentes en cualquier caso","Sin await el método no se llega a ejecutar en absoluto","Con await se ejecuta dos veces el método"],2,"Sin await, el código continúa de inmediato mientras la tarea corre en paralelo; solo con await se espera el resultado y se obtiene el valor T en vez del Task<T>."),
  sqr("¿Qué palabra clave es obligatoria en la firma de un método para poder usar 'await' dentro de su cuerpo?","async",["yield","static","virtual"],3,"'await' solo es válido dentro de un método (o lambda) marcado explícitamente como async; sin ese modificador, el compilador rechaza el uso de await."),
  sqr("¿Participa la palabra clave 'async' en la firma pública que ven los llamadores de un método (por ejemplo, para overload resolution)?","No, 'async' es un detalle de implementación interno; el llamador solo ve el tipo de retorno (Task, Task<T>, etc.), no si el método está marcado async",["Sí, el compilador genera una firma distinta por cada método async para overload resolution","Sí, 'async' cambia el tipo de retorno visible externamente a 'AsyncTask<T>'","No, porque los métodos async no pueden tener firma pública"],1,"async modifica cómo se implementa el cuerpo del método, pero no forma parte del contrato visible externamente: dos métodos que solo difieran en 'async' con la misma firma pública siguen siendo la misma firma para el llamador."),
  sqr("¿Qué convención de nomenclatura es habitual para métodos async en .NET, como se ve en 'ObtenerSaludoAsync'?","Sufijar el nombre del método con 'Async', para distinguirlo claramente de su posible contraparte síncrona",["Prefijar el nombre con 'Async', como 'AsyncObtenerSaludo'","No hay convención, cualquier nombre es igual de idiomático","Usar solo mayúsculas para métodos async"],0,"La convención ampliamente adoptada en .NET es agregar el sufijo 'Async' al nombre de los métodos que devuelven Task/Task<T> de forma asíncrona."),
 ]},
 {id:"m14-cancellation",title:"Cancelar con CancellationToken",summary:"CancellationTokenSource crea un token que se puede cancelar llamando a Cancel() (o programarlo con CancelAfter). CancellationToken.ThrowIfCancellationRequested() lanza OperationCanceledException si se solicitó cancelación. La cancelación es cooperativa: el código que nunca revisa el token sigue ejecutándose sin verse afectado; no detiene hilos por la fuerza.",code:"var cts = new CancellationTokenSource();\ncts.CancelAfter(2000);\n\ntry\n{\n    await TrabajoLargoAsync(cts.Token);\n}\ncatch (OperationCanceledException)\n{\n    Console.WriteLine(\"Cancelado\");\n}\n\nasync Task TrabajoLargoAsync(CancellationToken token)\n{\n    for (int i = 0; i < 10; i++)\n    {\n        token.ThrowIfCancellationRequested();\n        await Task.Delay(500, token);\n    }\n}",questions:[
  sqr("Si el código dentro de un bucle nunca llama a ThrowIfCancellationRequested ni revisa IsCancellationRequested, ¿lo detiene cts.Cancel()?","No; la cancelación es cooperativa, así que ese código sigue ejecutándose sin interrupción hasta que termine por su cuenta",["Sí, cts.Cancel() detiene forzosamente cualquier código en ejecución","Solo se detiene si el bucle usa Parallel.For","Sí, pero solo en aplicaciones de consola"],0,"CancellationToken no fuerza la detención de nada: el código que se está ejecutando debe consultar el token activamente para reaccionar a la cancelación."),
  sqr("¿Qué excepción lanza token.ThrowIfCancellationRequested() cuando IsCancellationRequested es true?","OperationCanceledException",["TaskCanceledException únicamente, sin relación con OperationCanceledException","InvalidOperationException","TimeoutException"],1,"ThrowIfCancellationRequested lanza OperationCanceledException (portando el token) cuando se solicitó la cancelación."),
  sqr("¿Qué hace cts.CancelAfter(2000) en el ejemplo?","Programa que Cancel() se invoque automáticamente tras 2000 milisegundos, sin bloquear el hilo que llamó a CancelAfter",["Bloquea el hilo actual durante 2000 milisegundos y luego cancela","Cancela inmediatamente y además espera 2000ms antes de continuar","Reinicia el token cada 2000 milisegundos indefinidamente"],2,"CancelAfter programa una cancelación diferida sin bloquear; tras el tiempo indicado, el runtime invoca Cancel() por sí mismo."),
  sqr("En 'await Task.Delay(500, token)', si el token se cancela durante esa espera de 500ms, ¿qué ocurre?","Task.Delay finaliza antes de tiempo lanzando una excepción de cancelación (TaskCanceledException), en vez de esperar los 500ms completos",["Task.Delay ignora el token y siempre espera los 500ms completos","El programa se cierra inmediatamente sin excepción","Task.Delay devuelve false en vez de lanzar una excepción"],0,"Los overloads de Task.Delay que aceptan un CancellationToken terminan anticipadamente arrojando una excepción de cancelación si el token se cancela antes del tiempo indicado."),
  sqr("¿Cuál es la relación entre CancellationTokenSource y CancellationToken?","CancellationTokenSource es quien puede iniciar la cancelación (con Cancel()); CancellationToken es el valor de solo lectura, derivado de la fuente, que se distribuye a los consumidores para que lo consulten",["Son la misma clase con dos nombres distintos","CancellationToken puede cancelar, y CancellationTokenSource solo consulta el estado","CancellationTokenSource se pasa a los métodos y CancellationToken permanece privado siempre"],0,"La fuente (Source) controla y dispara la cancelación; el token es la parte pasiva que se propaga y se consulta, sin poder disparar la cancelación por sí mismo."),
  sqr("¿Puede una única CancellationTokenSource cancelar varias operaciones independientes que recibieron su Token?","Sí, una sola llamada a Cancel() en la fuente afecta a todos los consumidores que tengan ese mismo token, sin importar cuántas operaciones lo estén usando",["No, cada operación necesita su propia CancellationTokenSource","Solo si las operaciones corren en el mismo hilo","Solo si se llama Cancel() una vez por cada consumidor"],1,"El mismo CancellationToken puede distribuirse a múltiples operaciones; todas verán IsCancellationRequested en true tras un único Cancel() de la fuente compartida."),
  sqr("¿Es TaskCanceledException un subtipo de OperationCanceledException?","Sí, TaskCanceledException deriva de OperationCanceledException, por lo que un catch de OperationCanceledException también la captura",["No, son clases sin relación de herencia entre sí","Es al revés: OperationCanceledException deriva de TaskCanceledException","Solo están relacionadas en .NET Framework, no en .NET moderno"],2,"TaskCanceledException es una subclase más específica de OperationCanceledException; capturar el tipo base también atrapa la excepción más específica."),
  sqr("En un bucle CPU-intensivo largo, ¿dónde conviene revisar IsCancellationRequested (o llamar ThrowIfCancellationRequested) para que la cancelación responda con rapidez?","Periódicamente dentro del propio bucle, en cada iteración o cada cierto número de ellas, no solo una vez antes de empezar",["Solo una vez, antes de iniciar el bucle","Solo una vez, después de que el bucle termine por completo","Nunca es necesario revisarlo dentro del bucle si se revisó al inicio del método"],0,"Revisar el token solo al principio no detecta una cancelación solicitada después; hay que consultarlo repetidamente durante el trabajo largo para responder oportunamente."),
  sqr("Cuando una tarea termina porque se lanzó OperationCanceledException por una cancelación solicitada a través de su propio token, ¿en qué TaskStatus queda esa tarea?","TaskStatus.Canceled, un estado distinto de Faulted",["TaskStatus.Faulted, igual que cualquier otra excepción","TaskStatus.RanToCompletion, como si hubiera terminado con éxito","TaskStatus.WaitingForActivation de forma indefinida"],1,"El runtime distingue una cancelación reconocida (vía el token de la propia tarea) como TaskStatus.Canceled, diferente de un fallo genérico (Faulted) por otra excepción."),
  sqr("Si nunca se llama a Cancel() sobre un CancellationTokenSource recién creado, ¿qué valor tiene su Token.IsCancellationRequested mientras tanto?","false, permanece así indefinidamente a menos que algo dispare la cancelación (Cancel, CancelAfter, o un timeout asociado)",["true desde el momento de la creación","Cambia aleatoriamente entre true y false","Lanza una excepción al consultarlo antes de llamar Cancel()"],3,"Sin ninguna llamada a Cancel() (directa o programada), el token nunca reporta cancelación solicitada; simplemente permanece en false."),
 ]},
 {id:"m14-async-errors",title:"Manejo de errores async",summary:"Al hacer await sobre una tarea que falló, la excepción original se relanza directamente (sin envolver) en el punto del await, así que un catch normal para ese tipo la captura. Si en cambio se usa .Result o .Wait(), .NET envuelve el fallo en AggregateException. Un método async void no puede ser envuelto en try/catch por su llamador: sus excepciones no capturadas escapan hacia el SynchronizationContext y suelen terminar la aplicación.",code:"async Task<int> DividirAsync(int a, int b)\n{\n    await Task.Delay(10);\n    return a / b;\n}\n\ntry\n{\n    int r = await DividirAsync(10, 0);\n}\ncatch (DivideByZeroException ex)\n{\n    Console.WriteLine($\"Error: {ex.Message}\");\n}",questions:[
  sqr("En el fragmento mostrado, ¿qué tipo de excepción llega exactamente al catch?","DivideByZeroException, el tipo original, sin envolver en AggregateException",["AggregateException, envolviendo la excepción original","TaskCanceledException","No llega ninguna excepción al catch"],0,"await desenvuelve la excepción almacenada en la tarea y la relanza con su tipo original, permitiendo capturarla con un catch normal para ese tipo específico."),
  sqr("Si en vez de 'await DividirAsync(10, 0)' se usara 'DividirAsync(10, 0).Result', ¿qué se lanzaría realmente?","AggregateException, con la DivideByZeroException original dentro de su InnerException/InnerExceptions",["DivideByZeroException directamente, igual que con await","Ninguna excepción, .Result simplemente devuelve 0","InvalidOperationException genérica sin relación con la división"],1,"Acceder a .Result (o llamar .Wait()) sobre una tarea fallida siempre envuelve el error en AggregateException, a diferencia del comportamiento de await."),
  sqr("¿Por qué se considera peligroso usar 'async void' quitando la posibilidad de manejo de errores normal?","Porque no hay ningún Task que el llamador pueda observar o esperar, así que una excepción no capturada dentro escapa directamente hacia el SynchronizationContext (o termina el proceso) sin que el try/catch del llamador la intercepte",["Porque 'async void' no compila en C# moderno","Porque 'async void' obliga a usar Thread.Sleep en vez de await","Porque 'async void' solo puede usarse dentro de clases selladas (sealed)"],2,"Al no devolver un Task, no existe un objeto que el llamador pueda envolver en try/catch ni observar; el error se propaga fuera del flujo normal de excepciones."),
  sqr("¿Cuál es el caso de uso legítimo, ampliamente aceptado, para 'async void'?","Manejadores de eventos, cuya firma delegada exige void y no puede cambiarse a Task",["Cualquier método que haga solamente una llamada await, sin excepción","Métodos Main de aplicaciones de consola","Todos los métodos privados de una clase, por convención"],3,"Los manejadores de eventos (por ejemplo, en UI) tienen una firma void impuesta por el delegado del evento; ese es prácticamente el único escenario donde 'async void' se considera aceptable."),
  sqr("Si Task.WhenAll agrupa varias tareas y más de una falla, pero solo haces 'await Task.WhenAll(tareas)' dentro de un try/catch simple, ¿ves todas las excepciones o solo una?","Solo ves la primera excepción relanzada por await; para ver todas hay que inspeccionar la propiedad Exception (AggregateException) de la tarea de WhenAll u observar cada tarea individual",["Ves automáticamente todas las excepciones combinadas en el mensaje del catch","No se lanza ninguna excepción si al menos una tarea tuvo éxito","Se lanza una excepción distinta por cada tarea fallida, de forma secuencial"],0,"await sobre Task.WhenAll también desenvuelve solo la primera excepción; el resto queda accesible a través de la propiedad Exception de la tarea agregada si se necesita inspeccionarlas todas."),
  sqr("¿Qué TaskStatus tiene una tarea después de que una excepción no controlada terminó su ejecución interna?","Faulted",["Canceled","RanToCompletion","WaitingToRun"],1,"Cuando el delegado de una tarea lanza una excepción no controlada, la tarea queda en estado Faulted, distinto de Canceled (reservado para cancelaciones explícitas)."),
  sqr("Dentro de un método async Task, ¿los try/catch que envuelven un await se comportan igual que un try/catch sobre una llamada síncrona equivalente?","Sí: gracias a la máquina de estados generada por el compilador, las excepciones que ocurren en el await se propagan hacia el catch como si el código fuera secuencial",["No, dentro de métodos async los catch nunca capturan nada de un await","Solo funciona si el await está en la primera línea del método","No, se necesita un catch especial llamado 'catch async'"],0,"El compilador genera código que hace que las excepciones lanzadas durante el await se propaguen igual que en código síncrono normal, permitiendo un try/catch convencional alrededor."),
  sqr("Si un método 'async Task<T>' lanza una excepción de validación de forma síncrona, antes de llegar a su primer await, ¿el llamador la recibe como una excepción síncrona inmediata al invocar el método, o solo al esperar (await) el Task devuelto?","Solo al esperar (await, o inspeccionar) el Task devuelto: la excepción queda capturada dentro del Task en lugar de lanzarse de forma síncrona en la línea de la llamada",["Siempre se lanza de forma síncrona en la línea donde se invoca el método, antes de cualquier await del llamador","Nunca se propaga, la excepción se pierde silenciosamente","Solo se propaga si el método está marcado con [Serializable]"],0,"Para un método async Task/Task<T> (a diferencia de async void), cualquier excepción —incluso una lanzada antes del primer await— se captura y se almacena en el Task devuelto; el llamador solo la ve al observarlo (await, .Result, etc.)."),
  sqr("Si una tarea 'fire-and-forget' (lanzada sin await ni ninguna otra forma de observarla) termina fallando, ¿qué riesgo específico implica ese patrón?","El error queda efectivamente silenciado/ignorado por el código, dificultando detectar y depurar fallos reales, aunque la aplicación en general puede seguir corriendo",["El programa se detiene inmediatamente sin ninguna forma de evitarlo","Se relanza automáticamente en el hilo principal como si fuera síncrona","Convierte automáticamente la excepción en un warning de compilación"],0,"No observar una tarea (ni con await, ni revisando su Exception) significa que el error queda esencialmente ignorado por el flujo normal del programa, lo cual es una mala práctica aunque no siempre provoque un crash inmediato."),
  sqr("¿Cuál es la forma recomendada de propagar una excepción de bajo nivel capturada como la causa de una nueva excepción de más alto nivel dentro de un método async?","'throw new MiExcepcion(\"mensaje\", ex);' pasando la excepción original como innerException",["'throw ex;' siempre, para simplificar el manejo","Ignorar la excepción original y solo registrar un mensaje genérico en consola","Reemplazar 'ex' por null en el nuevo throw para evitar referencias circulares"],1,"Encadenar la excepción original como innerException conserva la causa raíz completa, útil tanto en código síncrono como asíncrono al envolver errores en un tipo más específico."),
 ]},
 {id:"m14-parallel-whenall",title:"Parallel y Task.WhenAll",summary:"Task.WhenAll espera de forma concurrente varias tareas asíncronas ya iniciadas (ideal para trabajo ligado a E/S, como red o disco), agregando resultados sin bloquear hilos mientras se espera. Parallel.For/Parallel.ForEach ejecutan un delegado síncrono repartido entre varios hilos del thread pool (ideal para trabajo intensivo de CPU), bloqueando el hilo llamador hasta terminar todas las iteraciones.",code:"var tareas = urls.Select(url => DescargarAsync(url));\nstring[] resultados = await Task.WhenAll(tareas);\n\nParallel.For(0, 1000, i =>\n{\n    resultado[i] = CalcularIntensivo(i);\n});",questions:[
  sqr("¿Para qué tipo de carga de trabajo es más adecuado Task.WhenAll?","Trabajo ligado a E/S (red, disco) ejecutado de forma concurrente, ya que no bloquea hilos mientras las operaciones esperan",["Cálculos intensivos de CPU que saturan varios núcleos","Operaciones que deben ejecutarse estrictamente en orden secuencial","Únicamente operaciones que no pueden fallar nunca"],0,"Task.WhenAll brilla en operaciones asíncronas de E/S, donde el hilo se libera mientras se espera respuesta de la red o el disco, permitiendo alta concurrencia sin muchos hilos bloqueados."),
  sqr("¿Para qué tipo de carga de trabajo es más adecuado Parallel.For/Parallel.ForEach?","Trabajo intensivo de CPU que se puede dividir en partes independientes y ejecutar en paralelo usando varios núcleos",["Llamadas de red concurrentes a servicios externos","Operaciones que dependen estrictamente de E/S lenta","Cualquier bucle, sin importar su tipo de carga"],1,"Parallel.For/ForEach usan varios hilos activos del thread pool para procesar cómputo real en paralelo, siendo ideales cuando el cuello de botella es CPU, no espera de E/S."),
  sqr("¿Task.WhenAll(tareas) inicia por sí mismo las tareas del arreglo que recibe?","No: las tareas ya deben estar iniciadas (por ejemplo, por haber invocado el método async correspondiente); WhenAll solo espera a que todas terminen",["Sí, WhenAll llama internamente Start() sobre cada tarea antes de esperar","Sí, pero solo si las tareas fueron creadas con 'new Task(...)'","No, y por eso siempre lanza una excepción si alguna tarea no está iniciada"],0,"Al llamar DescargarAsync(url) para cada url ya se inició esa operación; WhenAll simplemente combina y espera esas tareas ya en marcha, no las lanza."),
  sqr("Si usas Parallel.ForEach con una lambda async, como 'Parallel.ForEach(items, async item => await ProcesarAsync(item))', ¿qué problema surge?","Parallel.ForEach no espera (no hace await) el Task devuelto por la lambda async; considera cada iteración 'terminada' de inmediato aunque el trabajo real siga en curso, dificultando el control de errores y de finalización real",["El código no compila porque Parallel.ForEach prohíbe lambdas async","Se ejecuta de forma perfectamente equivalente a usar Task.WhenAll","Lanza una excepción de compilación por falta de await"],1,"Parallel.ForEach espera delegados síncronos (Action<T>); al pasarle una lambda async, obtiene un Task por cada iteración pero no lo observa ni espera, generando ejecución descontrolada y errores silenciados."),
  sqr("¿Parallel.For(0, 1000, i => { ... }) bloquea el hilo que lo invoca hasta que todas las iteraciones terminan?","Sí, es una llamada síncrona que retorna únicamente cuando el conjunto completo de iteraciones ha finalizado",["No, retorna de inmediato y las iteraciones continúan en segundo plano","Solo bloquea si se usa un CancellationToken","No, se comporta igual que Task.Run, retornando un Task"],0,"A diferencia de las APIs asíncronas, Parallel.For/ForEach son llamadas bloqueantes: el hilo que las invoca espera hasta que todas las iteraciones concluyan."),
  sqr("Si una de las tareas dentro del grupo pasado a Task.WhenAll falla, ¿las demás tareas del grupo se cancelan automáticamente?","No, WhenAll no cancela a las demás; todas continúan ejecutándose hasta su propio final (éxito o fallo) y WhenAll simplemente espera a que todas terminen antes de propagar la excepción",["Sí, WhenAll cancela inmediatamente todas las tareas restantes","Sí, pero solo si se pasó un CancellationToken compartido explícitamente","No se puede saber sin ejecutar el código, es indeterminado por diseño"],0,"Task.WhenAll no implica cancelación automática de las tareas hermanas; solo agrega su espera y, al completarse todas, expone el primer error si alguna falló."),
  sqr("¿Qué tipo devuelve 'Task.WhenAll(IEnumerable<Task<string>> tareas)'?","Task<string[]>, un arreglo con el resultado de cada tarea en el mismo orden en que se pasaron",["Task<string>, concatenando todos los resultados en un solo string","void, no puede usarse con await","Task<List<Task<string>>>, anidando las tareas originales"],1,"WhenAll sobre Task<T>[] produce Task<T[]>: al esperarlo obtienes un arreglo con los resultados individuales en el orden correspondiente a las tareas de entrada."),
  sqr("¿Para qué sirve ParallelOptions.MaxDegreeOfParallelism al usar Parallel.For?","Para limitar cuántos hilos/iteraciones concurrentes como máximo se ejecutan a la vez, evitando saturar el CPU o el thread pool",["Para forzar que todas las iteraciones corran en un único hilo obligatoriamente","Para definir cuántas veces se repite el bucle completo","Para establecer un tiempo límite total de ejecución del bucle"],2,"MaxDegreeOfParallelism acota el grado de paralelismo real usado, útil cuando no conviene usar todos los núcleos/hilos disponibles simultáneamente."),
  sqr("Si necesitas hacer 1000 llamadas HTTP concurrentes a un servicio externo, ¿por qué Parallel.ForEach suele ser una mala elección frente a Task.WhenAll con llamadas async?","Porque Parallel.ForEach consumiría hilos del thread pool bloqueados por cada llamada, mientras que Task.WhenAll con operaciones async no bloquea hilos mientras espera la red, permitiendo mucha más concurrencia con menos recursos",["Porque Parallel.ForEach no puede ejecutar más de 10 iteraciones a la vez","Porque las llamadas HTTP no pueden hacerse dentro de un Parallel.ForEach por restricciones del compilador","Porque Task.WhenAll siempre es más lento que Parallel.ForEach en cualquier escenario"],0,"El patrón correcto para muchas operaciones de E/S concurrentes es la asincronía basada en Task (WhenAll), que no ata un hilo por cada llamada en espera, a diferencia de bloquear hilos del thread pool con Parallel.ForEach."),
  sqr("¿Qué diferencia hay entre Task.WhenAny y Task.WhenAll?","WhenAny completa tan pronto como termina la PRIMERA tarea del grupo (devolviendo esa tarea); WhenAll espera a que TODAS las tareas del grupo terminen",["WhenAny y WhenAll son sinónimos exactos, solo cambia el nombre","WhenAny espera a todas las tareas y WhenAll solo a la primera","WhenAny solo funciona con Task<T>, nunca con Task simple"],1,"WhenAny resuelve en cuanto una sola tarea del conjunto finaliza (útil para timeouts o 'el que responda primero'); WhenAll requiere que todas hayan finalizado."),
 ]},
 {id:"m14-race-conditions",title:"Race conditions",summary:"Una race condition ocurre cuando varios hilos/tareas acceden y modifican estado compartido de forma concurrente sin sincronización, haciendo que el resultado dependa de un orden de ejecución impredecible. Incluso 'contador++' no es atómico (implica leer, sumar y escribir en pasos separados), así que incrementos concurrentes pueden perderse. Se corrige con lock, con la clase Interlocked para operaciones simples, o evitando estado mutable compartido.",code:"int contador = 0;\n\nParallel.For(0, 100000, _ =>\n{\n    contador++; // no es atómico: puede perder incrementos\n});\n\nConsole.WriteLine(contador); // valor final impredecible, normalmente < 100000",questions:[
  sqr("En el fragmento mostrado, ¿está garantizado que 'contador' termine valiendo exactamente 100000?","No; por la falta de sincronización sobre 'contador++', es habitual que el valor final sea menor a 100000 y varíe entre ejecuciones",["Sí, .NET garantiza que Parallel.For siempre produce el resultado matemáticamente correcto","Sí, porque los enteros de 32 bits son inherentemente atómicos en cualquier operación","No, y además el programa lanza una excepción cada vez que esto sucede"],0,"Como contador++ no es atómico, incrementos concurrentes pueden pisarse entre sí, perdiendo actualizaciones y produciendo un resultado final impredecible, típicamente menor al esperado."),
  sqr("¿Qué es, con precisión, una race condition?","Una condición en la que la corrección del programa depende del orden/tiempo relativo, no determinista, en que se ejecutan operaciones concurrentes sobre estado compartido",["Cualquier programa que use más de un hilo, sin excepción","Un error exclusivo de sintaxis que el compilador siempre detecta","Un tipo de excepción concreta lanzada por el runtime de .NET"],1,"Una race condition no es un tipo de excepción; es un defecto de diseño donde el resultado correcto depende de una sincronización de tiempos que no está garantizada."),
  sqr("¿Por qué 'contador++' no es una operación atómica a nivel de máquina?","Porque internamente implica al menos tres pasos separados: leer el valor actual, sumarle uno, y escribir el resultado de vuelta; otro hilo puede intercalarse entre esos pasos",["Porque 'contador++' en realidad ejecuta una consulta a una base de datos internamente","Porque los enteros en C# se almacenan como texto internamente","Porque el operador ++ solo existe en pseudocódigo, no en C# real"],0,"El incremento se descompone en leer-modificar-escribir; sin sincronización, dos hilos pueden leer el mismo valor antes de que ninguno escriba el resultado, perdiendo un incremento."),
  sqr("¿Cómo corrige la clase 'lock' este tipo de problema sobre una sección crítica?","Serializa el acceso: solo un hilo a la vez puede ejecutar el bloque protegido, evitando que dos hilos lean/escriban la variable compartida simultáneamente",["Divide automáticamente el trabajo entre más hilos disponibles","Convierte el bloque protegido en código asíncrono automáticamente","Elimina la necesidad de declarar la variable compartida"],3,"lock (Monitor.Enter/Exit internamente) garantiza exclusión mutua: mientras un hilo está dentro del bloque protegido, ningún otro hilo puede entrar simultáneamente a ese mismo bloque."),
  sqr("¿Qué ventaja tiene usar Interlocked.Increment(ref contador) en vez de un lock completo para este caso puntual?","Realiza el incremento como una única operación atómica a nivel de CPU, evitando la sobrecarga de adquirir/liberar un lock completo para una operación tan simple",["Interlocked.Increment ejecuta el incremento en paralelo en varios hilos a la vez sobre la misma variable","Es exactamente igual de costoso que un lock en todos los casos","Interlocked solo funciona con tipos string, no con int"],2,"Interlocked ofrece operaciones atómicas de bajo nivel (increment, decrement, exchange, etc.) más livianas que un lock completo para casos simples como sumar 1 a una variable compartida."),
  sqr("¿Pueden ocurrir race conditions también con código async/await concurrente (como varias tareas de Task.WhenAll) sobre el mismo objeto, incluso sin usar hilos explícitos nuevos?","Sí, si varias operaciones asíncronas concurrentes leen y modifican el mismo estado mutable compartido sin sincronización, el mismo problema puede aparecer",["No, race conditions solo pueden ocurrir con Parallel.For o hilos explícitos, nunca con async/await","No, await siempre serializa automáticamente todo el acceso a variables compartidas","Solo puede ocurrir si se usa Thread.Sleep dentro del código async"],0,"La concurrencia (aunque no use hilos del sistema operativo explícitos) puede seguir generando operaciones intercaladas sobre el mismo estado mutable, produciendo el mismo tipo de problema."),
  sqr("¿En qué se diferencia conceptualmente un deadlock de una race condition?","Un deadlock es cuando dos o más hilos quedan bloqueados esperándose mutuamente para siempre; una race condition es un resultado incorrecto/impredecible por falta de sincronización, sin que necesariamente haya bloqueo",["Son exactamente el mismo fenómeno con dos nombres distintos","Un deadlock siempre es menos grave que una race condition","Una race condition siempre termina bloqueando el programa por completo, igual que un deadlock"],1,"Deadlock implica bloqueo permanente mutuo (por ejemplo, locks adquiridos en orden cruzado); race condition implica un resultado incorrecto por interleaving no controlado, sin que el programa necesariamente se congele."),
  sqr("¿Es cierto que agregar 'lock' alrededor de cada operación del programa siempre soluciona cualquier problema de concurrencia sin ningún costo?","No: el uso excesivo o mal ordenado de locks puede degradar seriamente el rendimiento (al serializar trabajo que podría ser paralelo) e incluso introducir deadlocks si el orden de adquisición no es consistente",["Sí, más locks siempre es estrictamente mejor y sin ninguna desventaja","No, porque 'lock' está deprecado y ya no se puede usar en C# moderno","Sí, siempre y cuando se use 'lock(this)' en cada clase"],0,"La sincronización debe ser mínima y bien diseñada: proteger solo lo necesario. Un exceso de locks reduce el paralelismo real y, con orden inconsistente entre múltiples locks, puede provocar deadlocks."),
  sqr("¿Qué colecciones de .NET ayudan a evitar tener que implementar sincronización manual para escenarios comunes de productor/consumidor concurrente?","Las de System.Collections.Concurrent, como ConcurrentDictionary o ConcurrentQueue, que ya son seguras para uso concurrente internamente",["List<T> y Dictionary<T,K> estándar, que ya son seguras para concurrencia por defecto","Array, porque los arreglos son intrínsecamente thread-safe en C#","No existen colecciones de este tipo en .NET; siempre hay que sincronizar manualmente"],1,"System.Collections.Concurrent ofrece colecciones diseñadas específicamente para acceso concurrente seguro, evitando tener que envolver manualmente List<T>/Dictionary<T,K> (que NO son thread-safe) con locks propios."),
  sqr("Si dos operaciones concurrentes solo LEEN la misma variable compartida, sin que ninguna la modifique, ¿existe riesgo de race condition sobre esa variable?","No, la lectura concurrente pura sin ninguna escritura simultánea es segura; el riesgo de race condition aparece cuando al menos una operación escribe mientras otra lee o escribe",["Sí, cualquier acceso concurrente, incluso de solo lectura, siempre es una race condition","Sí, pero únicamente si la variable es de tipo string","No, pero solo si el programa corre en un único núcleo de CPU"],0,"Las race conditions surgen de accesos concurrentes donde al menos uno modifica el estado compartido; múltiples lectores simultáneos sin escritores no generan por sí solos ese problema."),
 ]},
 {id:"m14-configureawait",title:"ConfigureAwait",summary:"ConfigureAwait(false) indica que la continuación después del await no necesita reanudarse en el SynchronizationContext (o TaskScheduler) originalmente capturado, permitiendo continuar en cualquier hilo del thread pool. No cancela, no acelera ni cambia cómo se ejecuta la operación esperada: solo afecta dónde se reanuda el código posterior al await. Se recomienda sobre todo en código de librería para evitar deadlocks y overhead de cambio de contexto en apps con SynchronizationContext (UI, ASP.NET clásico).",code:"public async Task<string> LeerConfigAsync(string ruta)\n{\n    string contenido = await File.ReadAllTextAsync(ruta).ConfigureAwait(false);\n    return contenido.Trim();\n}",questions:[
  sqr("¿Qué es exactamente lo que cambia .ConfigureAwait(false)?","Si la continuación posterior al await intenta reanudarse en el contexto de sincronización originalmente capturado o no; no cambia cómo se ejecuta la operación esperada en sí",["La velocidad de ejecución de la operación de E/S que se está esperando","El resultado que produce la operación esperada","El tipo de dato que devuelve el método async"],0,"ConfigureAwait(false) solo decide el comportamiento de reanudación de la continuación (en qué contexto/hilo sigue el código después del await), sin alterar la ejecución de la operación asíncrona en sí."),
  sqr("¿Cancela ConfigureAwait(false) la operación esperada si esta tarda demasiado?","No, ConfigureAwait no tiene relación alguna con cancelación; para eso se usa CancellationToken",["Sí, cancela automáticamente cualquier operación que exceda cierto tiempo","Sí, pero solo si se combina con Task.Delay","No cancela, pero sí pausa la operación indefinidamente"],0,"Cancelar operaciones es responsabilidad de CancellationToken; ConfigureAwait solo afecta el contexto de reanudación de la continuación, nada relacionado con detener o limitar tiempo de la operación."),
  sqr("¿Hace ConfigureAwait(false) que la operación esperada (por ejemplo, File.ReadAllTextAsync) se ejecute más rápido o en paralelo?","No, no cambia la velocidad ni el paralelismo de la operación esperada; solo evita el paso extra de volver al contexto original al reanudar",["Sí, siempre acelera la operación al evitar el contexto original","Sí, obliga a que la operación se ejecute en paralelo en varios núcleos","Solo la acelera si el archivo es mayor a cierto tamaño"],0,"El posible beneficio de ConfigureAwait(false) es evitar el overhead de reencolar la continuación en un contexto específico; no acelera ni paraleliza la operación de E/S en sí misma."),
  sqr("¿Qué problema clásico puede causar OMITIR ConfigureAwait(false) en código de librería que después es esperado con .Result o .Wait() desde una app con SynchronizationContext (por ejemplo, UI clásica o ASP.NET Framework)?","Un deadlock, porque la continuación intenta volver a entrar en el contexto original, el cual está bloqueado esperando sincrónicamente ese mismo resultado",["Una pérdida de datos silenciosa en el resultado devuelto","Un aumento del uso de memoria sin relación con el hilo de ejecución","La cancelación automática y silenciosa de la operación"],1,"El caso clásico de deadlock ocurre cuando el hilo de UI/ASP.NET clásico bloquea sincrónicamente esperando un Task cuya continuación necesita volver a ese mismo hilo, que está ocupado esperando; ConfigureAwait(false) evita ese intento de volver al contexto original."),
  sqr("En ASP.NET Core moderno, ¿existe por defecto un SynchronizationContext que capturar en cada await?","No, ASP.NET Core no tiene SynchronizationContext por defecto, por lo que ConfigureAwait(false) aporta menos beneficio ahí (aunque sigue siendo válido y sin efectos negativos usarlo)",["Sí, y es idéntico al de WinForms/WPF","Sí, y es obligatorio usar ConfigureAwait(true) explícitamente en cada await","No, y por eso ConfigureAwait(false) está prohibido en ASP.NET Core"],0,"A diferencia de UI clásica o ASP.NET Framework, ASP.NET Core no usa SynchronizationContext por defecto, así que el problema de deadlock que motiva ConfigureAwait(false) es mucho menos relevante ahí."),
  sqr("¿Cuál es la sintaxis correcta para aplicar ConfigureAwait sobre una tarea que se va a esperar?","Se llama sobre la propia tarea antes de await, como 'await tarea.ConfigureAwait(false)'",["Se coloca como atributo sobre el método async completo, como '[ConfigureAwait(false)]'","Se pasa como segundo parámetro del propio await, como 'await(tarea, false)'","Se configura una sola vez de forma global para todo el proyecto automáticamente"],0,"ConfigureAwait es un método de instancia de Task/Task<T> que se encadena antes del await, por ejemplo 'await miTarea.ConfigureAwait(false)'."),
  sqr("¿En qué tipo de código se recomienda tradicionalmente aplicar ConfigureAwait(false) de forma consistente?","En código de librería reutilizable, para no imponer a quien la consuma un comportamiento de contexto específico ni arriesgar deadlocks en su aplicación",["Únicamente en el método Main de aplicaciones de consola","Solo en manejadores de eventos de UI, nunca en otro lugar","En ningún caso, su uso está completamente desaconsejado en C# moderno"],1,"La guía clásica es aplicar ConfigureAwait(false) en librerías (que no controlan el contexto del consumidor), mientras que el código de aplicación final que necesita volver al hilo de UI puede omitirlo intencionalmente."),
  sqr("Si un método usa 'await tarea.ConfigureAwait(false)' sobre una Task<string>, ¿sigue pudiendo obtenerse el resultado string tras el await?","Sí, ConfigureAwait no cambia qué valor se obtiene con await, solo afecta el contexto de reanudación; el resultado sigue siendo el string esperado",["No, ConfigureAwait(false) descarta el resultado producido por la tarea","No, se debe usar .Result después de ConfigureAwait, nunca await","Sí, pero el tipo cambia a object y requiere un cast"],0,"ConfigureAwait(false) es transparente respecto al valor obtenido: sigue pudiendo hacerse 'string resultado = await tarea.ConfigureAwait(false);' con total normalidad."),
  sqr("Si dentro de un manejador de evento de UI usas ConfigureAwait(false) y luego, tras el await, intentas actualizar directamente un control visual, ¿qué riesgo corres?","Que el código posterior al await ya no esté ejecutándose en el hilo de UI, provocando un error o comportamiento incorrecto al tocar el control desde un hilo que no es el de UI",["Ninguno, ConfigureAwait(false) garantiza que siempre se vuelva al hilo de UI de todas formas","El programa se congelaría inmediatamente en un deadlock garantizado","La actualización del control sería más rápida gracias a ConfigureAwait(false)"],0,"Justamente por evitar volver al contexto original, el código posterior al await puede ejecutarse en un hilo del thread pool distinto al de UI, lo que rompe el acceso directo y seguro a controles visuales."),
  sqr("¿Qué mecanismo interno es el que ConfigureAwait(false) evita al reanudar la continuación después del await?","Capturar el SynchronizationContext.Current (o el TaskScheduler actual) antes de esperar, y luego publicar (post) la continuación de vuelta a través de él",["El uso del thread pool en cualquier forma, incluso para la operación original","La creación de la máquina de estados generada por el compilador para el método async","El registro de excepciones dentro del Task devuelto por el método"],0,"El mecanismo evitado es la captura y posterior reenvío (post) de la continuación a través del SynchronizationContext/TaskScheduler original; ConfigureAwait(false) simplemente omite ese paso."),
 ]},
 {id:"m14-challenge",title:"Reto asíncrono",summary:"Reto integrador: descargar varios recursos de forma concurrente con Task.WhenAll, admitir cancelación cooperativa mediante CancellationToken, y manejar errores individuales sin que el fallo de una descarga oculte ni cancele silenciosamente las demás.",code:"public static async Task<string[]> DescargarTodoAsync(IEnumerable<string> urls, CancellationToken token)\n{\n    var tareas = urls.Select(url => DescargarAsync(url, token)).ToList();\n\n    try\n    {\n        return await Task.WhenAll(tareas);\n    }\n    catch (OperationCanceledException)\n    {\n        Console.WriteLine(\"Descarga cancelada\");\n        throw;\n    }\n}\n\nasync Task<string> DescargarAsync(string url, CancellationToken token)\n{\n    token.ThrowIfCancellationRequested();\n    await Task.Delay(200, token); // simula E/S de red\n    return $\"contenido de {url}\";\n}",questions:[
  sqr("En DescargarTodoAsync, ¿en qué momento se lanzan realmente las descargas individuales (DescargarAsync)?","Al ejecutar el Select dentro de 'urls.Select(url => DescargarAsync(url, token)).ToList()', ya que cada invocación de DescargarAsync empieza a ejecutarse de inmediato",["Solo cuando Task.WhenAll las invoca internamente","Solo si el token nunca se cancela","Una por una, secuencialmente, cada vez que se hace await dentro de WhenAll"],0,"Select con ToList() fuerza la evaluación inmediata, invocando DescargarAsync para cada url y arrancando cada tarea de inmediato, antes de llegar siquiera a Task.WhenAll."),
  sqr("Si se cancela el token mientras las descargas están en curso, ¿qué relanza el catch dentro de DescargarTodoAsync gracias a 'throw;'?","La misma OperationCanceledException capturada, preservando su stack trace original, en vez de una nueva excepción",["Una nueva excepción genérica sin relación con la cancelación","Nada; 'throw;' suprime la excepción en este contexto","AggregateException envolviendo la excepción original"],0,"'throw;' dentro de un catch relanza la excepción ya capturada conservando su información original, a diferencia de construir una nueva con 'throw new ...' o de usar 'throw ex;'."),
  sqr("¿Por qué DescargarAsync llama a 'token.ThrowIfCancellationRequested()' al inicio, antes incluso de hacer await Task.Delay?","Para responder de inmediato si la cancelación ya fue solicitada antes de siquiera iniciar el trabajo simulado de esa descarga en particular, evitando trabajo innecesario",["Es opcional y no cambia el comportamiento en ningún caso","Para forzar que la tarea nunca se complete","Porque Task.Delay no acepta CancellationToken como parámetro"],0,"Revisar el token al inicio evita arrancar trabajo (aunque sea breve) para una operación que ya debería considerarse cancelada, mejorando la capacidad de respuesta."),
  sqr("Si una de las descargas falla con una excepción distinta a cancelación (por ejemplo, una excepción de red) mientras las demás siguen en curso, ¿Task.WhenAll cancela automáticamente las demás tareas del grupo?","No, WhenAll no cancela por sí mismo al resto; todas continúan hasta su propio desenlace, y WhenAll espera a que todas terminen antes de propagar el primer error observado",["Sí, cualquier falla en una tarea cancela inmediatamente todas las demás dentro del mismo WhenAll","Solo se cancelan las tareas restantes si comparten el mismo CancellationTokenSource explícitamente indicado a WhenAll","Sí, pero solo las tareas que aún no hayan empezado a ejecutarse"],0,"Task.WhenAll no implica cancelación cruzada automática entre las tareas agrupadas; cada una sigue su curso de forma independiente hasta terminar, sea con éxito o con fallo."),
  sqr("¿Qué tipo tiene el valor devuelto por 'await Task.WhenAll(tareas)' en este reto, dado que 'tareas' es una lista de Task<string>?","string[], con el contenido descargado de cada url en el mismo orden en que se generaron las tareas",["string, concatenando todo el contenido en un único valor","List<Task<string>>, la lista original sin cambios","void, solo se usa para esperar sin producir resultado"],0,"Task.WhenAll sobre una colección de Task<string> produce, al esperarla, un string[] con un resultado por cada tarea en el orden correspondiente."),
  sqr("Si se quisiera limitar la cantidad de descargas concurrentes activas al mismo tiempo (por ejemplo, máximo 5 a la vez) en este reto, ¿qué herramienta de .NET sería la más adecuada para ese propósito, en vez de lanzar todas con Task.WhenAll sin límite?","Un SemaphoreSlim que cada descarga adquiere antes de trabajar y libera al terminar, limitando cuántas corren en paralelo",["Aumentar el valor de CancelAfter en el CancellationTokenSource","Reemplazar Task.WhenAll por Parallel.For directamente","No existe forma de limitar la concurrencia en código asíncrono en .NET"],0,"SemaphoreSlim permite limitar cuántas operaciones asíncronas concurrentes se ejecutan a la vez, siendo la herramienta habitual para acotar el paralelismo en escenarios async sin bloquear hilos innecesariamente."),
  sqr("¿Qué ocurriría si en DescargarTodoAsync se quitara por completo el try/catch, dejando solo 'return await Task.WhenAll(tareas);'?","Una OperationCanceledException seguiría propagándose igual hacia quien llamó a DescargarTodoAsync, solo que sin el mensaje \"Descarga cancelada\" por consola",["El programa ya no podría cancelarse nunca más","Se produciría un error de compilación por falta de manejo de excepciones","Las descargas se ejecutarían de forma síncrona en vez de concurrente"],0,"El try/catch en este reto solo añade un mensaje informativo y relanza con 'throw;'; sin él, la excepción de cancelación se propagaría igualmente hacia arriba, solo que sin ese log adicional."),
  sqr("¿Es correcto decir que Task.Delay(200, token) dentro de DescargarAsync bloquea un hilo del thread pool durante los 200ms de espera simulada?","No, Task.Delay con soporte de cancelación sigue siendo no bloqueante: no ocupa un hilo activo mientras espera, solo se reanuda cuando el tiempo pasa o el token se cancela",["Sí, reserva un hilo completo del thread pool durante toda la espera","Sí, pero solo si se omite el parámetro token","No bloquea nada, pero tampoco puede cancelarse una vez iniciado"],1,"Task.Delay es no bloqueante incluso con un CancellationToken: usa temporizadores internos en vez de mantener un hilo ocupado esperando, y además responde a la cancelación antes de que termine el tiempo completo."),
  sqr("Si 'urls' está vacío (sin ningún elemento), ¿qué ocurre al llamar DescargarTodoAsync(urls, token)?","Task.WhenAll sobre una colección vacía de tareas se completa de inmediato, devolviendo un arreglo string[] vacío, sin lanzar ninguna excepción",["Lanza ArgumentException porque no hay tareas para esperar","Se queda esperando indefinidamente porque no hay ninguna tarea que complete","Lanza NullReferenceException al intentar iterar la colección vacía"],0,"Task.WhenAll admite una colección vacía de tareas sin problema: se resuelve de inmediato con un arreglo vacío, ya que no hay nada pendiente que esperar."),
  sqr("¿Qué ventaja tiene pasar el mismo 'token' tanto a Task.WhenAll (indirectamente, a través de cada tarea) como a cada Task.Delay individual dentro de DescargarAsync, en vez de solo revisarlo una vez al inicio del programa?","Permite que la cancelación se propague y sea observada en múltiples puntos del trabajo en curso (antes de empezar cada descarga y durante cada espera), haciendo la respuesta a Cancel() más oportuna",["Ninguna, revisar el token una sola vez al inicio del programa es exactamente equivalente","Hace que las descargas se ejecuten más rápido en todos los casos","Evita por completo la posibilidad de fallos de red durante la descarga"],0,"Distribuir el token a cada punto relevante del trabajo (inicio de cada tarea, cada espera) es lo que hace efectiva la cancelación cooperativa; revisarlo solo una vez al principio del programa no detectaría una cancelación solicitada después."),
 ]},
 {id:"m15-debugger",title:"Debugger y breakpoints",summary:"Un breakpoint pausa la ejecución en una línea específica para inspeccionar variables, la pila de llamadas (call stack) y evaluar expresiones. Step Over (F10) ejecuta la línea actual sin entrar en los métodos que llama; Step Into (F11) entra dentro del método llamado; Step Out (Shift+F11) termina de ejecutar el método actual y vuelve al llamador. Los breakpoints condicionales solo pausan si una expresión booleana es verdadera.",code:"static int Sumar(int a, int b)\n{\n    int resultado = a + b; // breakpoint aquí para inspeccionar a, b y resultado\n    return resultado;\n}\n\nstatic void Main()\n{\n    int total = Sumar(2, 3);\n    Console.WriteLine(total);\n}",questions:[
  sqr("Si el debugger está pausado en la línea 'int total = Sumar(2, 3);' y presionas Step Into (F11), ¿qué ocurre?","La ejecución entra dentro del método Sumar, pausando en su primera línea ejecutable",["Ejecuta Sumar por completo sin pausar dentro y se detiene en la siguiente línea de Main","Termina toda la depuración inmediatamente","Salta directamente al final del programa"],1,"Step Into hace que el debugger entre al método invocado, permitiendo inspeccionar su ejecución paso a paso desde adentro."),
  sqr("Si en cambio, en esa misma línea, presionas Step Over (F10), ¿qué ocurre?","Sumar(2, 3) se ejecuta por completo de una vez (sin pausar dentro de él) y el debugger se detiene en la siguiente línea de Main",["Entra dentro de Sumar igual que Step Into","Detiene la depuración sin ejecutar nada más","Ejecuta el programa completo hasta el final sin más pausas"],2,"Step Over ejecuta el método llamado como una unidad completa, sin detenerse dentro de él, y continúa la pausa en la siguiente línea del método actual."),
  sqr("Si estando pausado DENTRO de Sumar presionas Step Out (Shift+F11), ¿qué ocurre?","Termina de ejecutar el resto de Sumar y regresa la pausa a Main, justo después de la llamada a Sumar",["Vuelve al inicio de Sumar para reejecutarlo desde cero","Sale completamente del debugger sin terminar el programa","Entra en un nuevo método llamado dentro de Sumar"],0,"Step Out completa la ejecución del método actual y devuelve el control (con una nueva pausa) al punto justo después de donde fue invocado."),
  sqr("¿Qué permite hacer un breakpoint condicional, por ejemplo configurado con la condición 'a == 5'?","Que la ejecución solo se detenga en ese breakpoint cuando la variable 'a' valga exactamente 5, ignorando las demás veces que se pase por esa línea",["Que el breakpoint se elimine automáticamente después de la primera vez que se cumpla la condición","Que el programa se detenga siempre en esa línea, sin importar la condición","Que se muestre un mensaje de error si 'a' no vale 5"],0,"Los breakpoints condicionales evalúan una expresión booleana cada vez que se alcanza esa línea, y solo pausan la ejecución si esa expresión resulta verdadera."),
  sqr("¿Qué información suele mostrar la ventana 'Call Stack' (pila de llamadas) mientras el debugger está pausado?","La secuencia de métodos que llevaron hasta el punto actual de ejecución, desde el punto de entrada hasta el método actualmente pausado",["El valor histórico de todas las variables usadas en el programa","La lista de todos los breakpoints activos en la solución","El uso de memoria total del proceso en ese instante"],1,"El Call Stack muestra la cadena de llamadas anidadas (quién llamó a quién) que llevó hasta la línea actualmente pausada, útil para entender el contexto de ejecución."),
  sqr("¿Para qué se usa típicamente la ventana Watch durante una sesión de depuración?","Para agregar expresiones o variables específicas y monitorear su valor mientras se avanza paso a paso por el código",["Para modificar automáticamente el código fuente mientras se depura","Para compilar el proyecto en modo Release","Para listar todos los archivos del proyecto"],0,"La ventana Watch permite fijar expresiones de interés (variables, propiedades, cálculos) y ver cómo cambian sus valores a medida que se avanza en la depuración."),
  sqr("¿Qué diferencia principal hay entre Debug.WriteLine y Console.WriteLine respecto a una compilación en modo Release (sin el símbolo DEBUG definido)?","Debug.WriteLine, al estar marcado con [Conditional(\"DEBUG\")], se elimina por completo del código compilado en Release; Console.WriteLine siempre se incluye y se ejecuta, sin importar la configuración",["Son exactamente equivalentes en cualquier configuración de compilación","Console.WriteLine se elimina en Release y Debug.WriteLine se mantiene siempre","Debug.WriteLine lanza una excepción si se compila en modo Release"],0,"Debug.WriteLine usa ConditionalAttribute(\"DEBUG\"), por lo que el compilador omite esas llamadas por completo si el símbolo DEBUG no está definido (como ocurre por defecto en builds Release); Console.WriteLine no tiene ese comportamiento condicional."),
  sqr("¿Qué permite hacer la ventana Immediate (Inmediato) durante una pausa del debugger?","Escribir y evaluar expresiones o pequeñas instrucciones de C# directamente en ese momento, incluyendo leer o incluso cambiar el valor de variables en memoria",["Solo permite ver el código fuente en modo solo lectura","Solo funciona antes de iniciar la depuración, no durante una pausa","Sirve exclusivamente para ver los mensajes de compilación"],0,"La ventana Immediate permite ejecutar expresiones arbitrarias de C# en el contexto actual de la pausa, útil para inspeccionar o incluso modificar el estado en vivo."),
  sqr("¿Qué logra activar la opción de 'romper cuando se lanza' (break on throw) una excepción específica, en vez de esperar a que quede sin manejar?","El debugger pausa la ejecución exactamente en la línea donde la excepción se lanza por primera vez, aunque más adelante exista un catch que la maneje",["Evita que la excepción se lance en absoluto","Convierte automáticamente esa excepción en una advertencia no bloqueante","Solo funciona si la excepción no tiene ningún catch en todo el programa"],0,"Esta opción permite detenerse en el punto exacto donde una excepción se origina (throw), incluso si luego un catch más arriba la captura, lo cual es útil para diagnosticar el origen real del problema."),
  sqr("Si colocas un breakpoint dentro de un bucle 'for' que se ejecuta 1000 veces sin ninguna condición, ¿cuántas veces se detendrá el debugger en ese breakpoint por defecto?","Hasta 1000 veces, una por cada iteración que llegue a esa línea, salvo que se le agregue una condición o se elimine el breakpoint antes",["Solo una vez, siempre, sin importar el número de iteraciones","Nunca, los breakpoints no funcionan dentro de bucles","Exactamente 10 veces, como límite por defecto del IDE"],0,"Sin una condición asociada, un breakpoint se activa cada vez que la ejecución llega a esa línea, por lo que en un bucle de 1000 iteraciones podría pausar hasta 1000 veces."),
 ]},
 {id:"m15-unit-tests",title:"Unit tests",summary:"Un unit test verifica automáticamente el comportamiento de una unidad pequeña de código (típicamente un método) de forma aislada, rápida y repetible, idealmente sin depender de bases de datos, red ni el sistema de archivos reales. En .NET, los frameworks más usados son xUnit ([Fact]/[Theory]), NUnit ([Test]/[TestCase]) y MSTest ([TestMethod]/[TestClass]); un proyecto de pruebas referencia el framework elegido y el proyecto bajo prueba.",code:"public class CalculadoraTests\n{\n    [Fact]\n    public void Sumar_DosPositivos_DevuelveSuma()\n    {\n        var calculadora = new Calculadora();\n\n        int resultado = calculadora.Sumar(2, 3);\n\n        Assert.Equal(5, resultado);\n    }\n}",questions:[
  sqr("¿Qué caracteriza principalmente a un unit test bien diseñado?","Es rápido, aislado (no depende de recursos externos reales como red o base de datos) y repetible: produce el mismo resultado cada vez que se ejecuta",["Debe tardar varios segundos ejecutando llamadas de red reales para ser válido","Depende siempre de que exista una base de datos real conectada","Solo puede verificar clases completas, nunca métodos individuales"],1,"La esencia de un unit test es aislar una unidad pequeña de comportamiento sin depender de infraestructura externa, para que sea rápido, confiable y determinista."),
  sqr("En xUnit, ¿qué atributo se usa para marcar un método de prueba simple, sin parámetros?","[Fact]",["[Test]","[TestMethod]","[UnitTest]"],0,"xUnit usa [Fact] para pruebas sin parámetros y [Theory] (combinado con datos) para pruebas parametrizadas."),
  sqr("¿Qué atributo usa MSTest (en vez de [Fact] de xUnit) para marcar un método de prueba?","[TestMethod]",["[Fact]","[Test]","[UnitOfWork]"],1,"MSTest usa [TestClass] sobre la clase y [TestMethod] sobre cada método de prueba, a diferencia de xUnit ([Fact]/[Theory]) o NUnit ([Test])."),
  sqr("¿Qué atributo usa NUnit para marcar un método de prueba simple?","[Test]",["[Fact]","[TestMethod]","[Should]"],0,"NUnit utiliza [TestFixture] sobre la clase y [Test] sobre cada método de prueba individual."),
  sqr("En el ejemplo mostrado, ¿qué verifica exactamente 'Assert.Equal(5, resultado)'?","Que el valor de 'resultado' sea igual a 5; si no lo es, la prueba falla reportando el valor esperado (5) contra el obtenido",["Que 'resultado' no sea null","Que 'resultado' sea mayor que 5","Que el tipo de 'resultado' sea int, sin comparar el valor"],0,"Assert.Equal(esperado, actual) compara ambos valores por igualdad; si difieren, la prueba se marca como fallida con un mensaje que indica ambos valores."),
  sqr("¿Por qué se considera mala práctica que un unit test dependa de una base de datos real en producción?","Porque introduce lentitud, no determinismo (datos que cambian) y acoplamiento a infraestructura externa, afectando la velocidad y confiabilidad de la suite de pruebas",["Porque .NET no permite técnicamente conectar a bases de datos desde pruebas","Porque las pruebas dejarían de compilar","Porque solo los tests de integración pueden compilar en C#"],1,"Un unit test aislado no debería depender de sistemas externos reales; esa responsabilidad es propia de pruebas de integración, no de unit tests puros."),
  sqr("¿Qué necesita típicamente un proyecto de pruebas en .NET para poder ejecutar los tests contra el código de la aplicación?","Una referencia de proyecto (ProjectReference) hacia el proyecto que contiene el código bajo prueba, además del paquete NuGet del framework de testing elegido",["Nada especial, cualquier proyecto puede ejecutar pruebas sin ninguna referencia","Debe copiarse manualmente el código fuente dentro del proyecto de pruebas","Solo puede funcionar si ambos proyectos están en el mismo archivo .cs"],0,"El proyecto de pruebas referencia tanto el framework de testing (xUnit, NUnit o MSTest) como, mediante ProjectReference, el proyecto cuyo código quiere probar."),
  sqr("¿Con qué comando de la CLI de .NET se ejecutan típicamente las pruebas de un proyecto?","dotnet test",["dotnet run --test","dotnet build --unit-tests","dotnet exec tests"],1,"dotnet test descubre y ejecuta las pruebas del proyecto (o solución) usando el framework de testing configurado, reportando resultados de éxito/fallo."),
  sqr("¿Qué significa que dos unit tests sean 'independientes' entre sí?","Que el resultado de uno no depende de que otro se haya ejecutado antes, ni del orden en que corran; cada uno puede ejecutarse de forma aislada y obtener el mismo resultado",["Que deben estar en archivos .cs completamente distintos","Que no pueden compartir el mismo namespace","Que deben ejecutarse siempre en threads distintos obligatoriamente"],0,"La independencia entre tests evita que fallos en cascada o estado compartido entre pruebas oculten o distorsionen resultados; cada test debe poder correr solo y dar el mismo resultado."),
  sqr("En el nombre 'Sumar_DosPositivos_DevuelveSuma' del método de prueba, ¿qué convención de nomenclatura común para tests se está siguiendo?","Método bajo prueba, escenario/condición, y resultado esperado, separados para que el nombre documente claramente qué se está verificando",["El nombre debe coincidir exactamente con el nombre del método de producción, sin agregar nada más","Los nombres de test no importan ni tienen convención alguna","Debe incluir siempre la fecha en que se escribió el test"],0,"Una convención habitual (Método_Escenario_ResultadoEsperado) hace que el nombre del test, por sí solo, describa qué comportamiento se está validando, sin necesidad de leer el cuerpo."),
 ]},
 {id:"m15-arrange-act-assert",title:"Arrange, Act, Assert",summary:"El patrón AAA estructura un test en tres secciones claras: Arrange (preparar datos, dependencias y el objeto bajo prueba), Act (ejecutar la acción/método concreto que se está probando, idealmente en una sola línea) y Assert (verificar que el resultado obtenido es el esperado). Mantiene los tests legibles y centrados en un único comportamiento.",code:"[Fact]\npublic void Retirar_MontoMayorAlSaldo_LanzaExcepcion()\n{\n    // Arrange\n    var cuenta = new CuentaBancaria(saldoInicial: 100);\n\n    // Act\n    Action retiro = () => cuenta.Retirar(500);\n\n    // Assert\n    Assert.Throws<SaldoInsuficienteException>(retiro);\n}",questions:[
  sqr("En el patrón AAA, ¿qué se hace específicamente en la sección 'Arrange'?","Se prepara todo lo necesario para el test: crear objetos, configurar dependencias y establecer el estado inicial, antes de ejecutar la acción bajo prueba",["Se ejecuta el método que se quiere probar","Se verifica que el resultado sea el esperado","Se limpia el entorno después de que el test terminó"],0,"Arrange establece el contexto y los datos de entrada necesarios; es la preparación previa a ejecutar la acción concreta que se va a validar."),
  sqr("¿Qué debería contener idealmente la sección 'Act' de un test bien escrito?","Únicamente la invocación de la acción o método concreto que se está probando, idealmente en una sola línea clara",["Toda la lógica de configuración de dependencias del test","Las aserciones (Assert) que validan el resultado","Comentarios explicando la intención general del test, sin código"],1,"Act debe limitarse a ejecutar la operación bajo prueba, manteniéndose corta y enfocada, separada claramente de la preparación (Arrange) y la verificación (Assert)."),
  sqr("En el ejemplo, ¿qué verifica 'Assert.Throws<SaldoInsuficienteException>(retiro)'?","Que al ejecutar la acción 'retiro' se lance efectivamente una excepción del tipo SaldoInsuficienteException; si no se lanza (o se lanza otro tipo), el test falla",["Que 'retiro' nunca se ejecute realmente","Que el saldo de la cuenta quede en 0 tras la operación","Que no se lance ninguna excepción durante la ejecución"],0,"Assert.Throws<T> ejecuta la acción indicada y falla el test si no se produce exactamente una excepción del tipo T (o de un tipo compatible) durante esa ejecución."),
  sqr("¿Por qué en el ejemplo se envuelve la llamada a Retirar en una 'Action retiro = () => cuenta.Retirar(500);' en lugar de llamarla directamente en el Act?","Porque Assert.Throws necesita recibir un delegado (una acción no ejecutada todavía) para poder invocarlo internamente y capturar la excepción que produzca, en vez de que la excepción se lance antes de llegar al Assert",["Porque C# no permite llamar métodos directamente dentro de un método de test","Porque Retirar(500) es un método asíncrono obligatoriamente","Porque de otra forma el compilador no permitiría pasar el número 500 como argumento"],0,"Si se llamara 'cuenta.Retirar(500)' directamente en la línea de Act, la excepción se lanzaría ahí mismo, antes de llegar a ninguna verificación; envolverla en un delegado permite que Assert.Throws la invoque y capture el resultado de forma controlada."),
  sqr("¿Qué ventaja principal aporta seguir consistentemente la estructura AAA en los tests de un proyecto?","Mejora la legibilidad: cualquier persona puede identificar rápidamente qué se prepara, qué se ejecuta y qué se verifica en cada test, sin tener que descifrar la intención",["Hace que los tests se ejecuten más rápido a nivel de CPU","Es un requisito obligatorio del compilador de C# para que el proyecto compile","Elimina por completo la necesidad de usar Assert en los tests"],0,"AAA es principalmente una convención de organización y legibilidad; no afecta la velocidad de ejecución ni es exigida por el compilador, pero facilita mantener y entender la suite de pruebas."),
  sqr("¿Es aceptable, según el espíritu de AAA, que un test tenga múltiples llamadas de Act distintas mezcladas con varias secciones de Assert intercaladas?","No es lo ideal: cada test debería enfocarse en un único comportamiento con un Act claro, evitando mezclar múltiples acciones y verificaciones entrelazadas que dificulten saber qué falló y por qué",["Sí, es la forma recomendada y más común de escribir tests en AAA","Sí, siempre que el archivo del test tenga menos de 100 líneas en total","Es indiferente, AAA no tiene ninguna relación con cuántas acciones tenga el test"],1,"Mezclar múltiples Act/Assert intercalados dificulta identificar cuál acción causó un fallo; la práctica recomendada es mantener cada test enfocado en verificar un único comportamiento concreto."),
  sqr("Si en 'Arrange' se crea 'var cuenta = new CuentaBancaria(saldoInicial: 100);' y en 'Act' se ejecuta 'cuenta.Retirar(500)', ¿qué comportamiento del sistema se está probando en este test específico?","El manejo del caso en que se intenta retirar un monto mayor al saldo disponible, verificando que se lance la excepción de dominio esperada en lugar de permitir el retiro",["Que el saldo inicial se haya guardado correctamente al crear la cuenta","Que el método Retirar exista como miembro público de la clase","Que la clase CuentaBancaria pueda instanciarse sin errores"],0,"El nombre del test y su Act/Assert dejan claro que el comportamiento bajo prueba es específicamente el rechazo de un retiro que excede el saldo disponible."),
  sqr("¿Debería la sección 'Assert' de un test contener lógica de negocio compleja (condicionales, bucles) para decidir si el test pasa o falla?","No; lo ideal es que Assert contenga verificaciones simples y directas sobre el resultado, evitando lógica compleja que pueda ocultar bugs en el propio test",["Sí, cuanta más lógica tenga el Assert, más confiable es el test","Sí, es obligatorio usar al menos un bucle for en cada Assert","Es indiferente, Assert nunca ejecuta código real en tiempo de prueba"],0,"Un Assert complejo con su propia lógica introduce el riesgo de que el propio test tenga bugs; se prefieren aserciones simples y explícitas sobre el resultado obtenido."),
  sqr("¿Qué ocurriría si se omitiera por completo la sección Assert del test del ejemplo, dejando solo Arrange y Act?","El test no verificaría nada realmente: podría 'pasar' incluso si el comportamiento real fuera incorrecto, dando una falsa sensación de cobertura",["El test fallaría automáticamente por no tener Assert","El compilador rechazaría el archivo por falta de aserciones","Assert.Throws se ejecutaría de todas formas de forma implícita"],0,"Sin una aserción real, un test puede pasar sin haber comprobado nada significativo sobre el comportamiento esperado, lo cual es peor que no tener el test: da una falsa confianza."),
  sqr("¿La sección 'Arrange' puede incluir la configuración de un test double (como un mock) además de crear el objeto bajo prueba?","Sí, configurar dependencias falsas (mocks, stubs) para el objeto bajo prueba forma parte natural de la preparación en Arrange",["No, los mocks solo pueden configurarse dentro de Act","No, usar mocks es incompatible con el patrón AAA","Solo si el mock se configura después del Assert"],0,"Arrange abarca toda la preparación necesaria, lo que incluye crear e inyectar dependencias reales o dobladas (mocks/stubs) antes de ejecutar la acción bajo prueba."),
 ]},
 {id:"m15-test-doubles",title:"Moq y test doubles",summary:"Un test double reemplaza una dependencia real dentro de un test (stub, mock, fake, spy). Moq es una librería popular de .NET para crear mocks: Mock<T> genera una implementación falsa de una interfaz o clase, .Setup(...).Returns(...) configura qué debe devolver ante cierta llamada, .Verify(...) comprueba que un método se llamó como se esperaba, e It.IsAny<T>() acepta cualquier argumento de ese tipo al configurar el comportamiento.",code:"var mockRepo = new Mock<IClienteRepositorio>();\nmockRepo.Setup(r => r.ObtenerPorId(1)).Returns(new Cliente { Id = 1, Nombre = \"Ana\" });\n\nvar servicio = new ClienteServicio(mockRepo.Object);\nCliente cliente = servicio.Buscar(1);\n\nmockRepo.Verify(r => r.ObtenerPorId(1), Times.Once);",questions:[
  sqr("¿Qué representa, en general, un 'test double' dentro de una prueba unitaria?","Un objeto que sustituye a una dependencia real (por ejemplo, un repositorio o un servicio externo) dentro de un test, permitiendo controlar y aislar su comportamiento",["Un test que se ejecuta exactamente dos veces","Una copia idéntica del código de producción, sin ninguna diferencia","Un tipo de excepción específico de los frameworks de testing"],0,"Test double es el término general para cualquier sustituto de una dependencia real en pruebas: mocks, stubs, fakes y spies son variantes específicas de esa idea."),
  sqr("En el ejemplo, ¿qué crea exactamente 'new Mock<IClienteRepositorio>()'?","Un objeto de Moq que puede generar una implementación falsa de la interfaz IClienteRepositorio, cuyo comportamiento se configura mediante Setup",["Una instancia real de la clase que implementa IClienteRepositorio en producción","Una conexión real a la base de datos usada por IClienteRepositorio","Un nuevo test automáticamente registrado en el framework"],0,"Mock<T> de Moq genera dinámicamente un doble de la interfaz o clase indicada, sobre el cual se configuran respuestas y se pueden verificar llamadas, sin tocar ninguna implementación real."),
  sqr("¿Qué logra '.Setup(r => r.ObtenerPorId(1)).Returns(new Cliente { Id = 1, Nombre = \"Ana\" })'?","Configura que, cuando se llame a ObtenerPorId con el argumento 1 sobre el mock, este devuelva ese objeto Cliente específico en lugar de ejecutar lógica real",["Verifica que ObtenerPorId ya haya sido llamado antes con el argumento 1","Modifica la base de datos real para que el cliente con Id 1 exista","Lanza una excepción si ObtenerPorId se llama con un argumento distinto de 1"],0,"Setup(...).Returns(...) define el comportamiento simulado: ante esa llamada específica, el mock devuelve el valor indicado, sin ejecutar ninguna implementación real."),
  sqr("¿Qué verifica '.Verify(r => r.ObtenerPorId(1), Times.Once)' al final del ejemplo?","Que el método ObtenerPorId(1) se haya llamado exactamente una vez sobre el mock durante la ejecución del test",["Que ObtenerPorId(1) devuelva siempre el mismo resultado en cualquier ejecución","Que el método ObtenerPorId exista en la interfaz IClienteRepositorio","Que el mock nunca haya sido usado durante el test"],0,"Verify permite comprobar, después del Act, que ciertas interacciones con el mock ocurrieron (o no) tantas veces como se espera; Times.Once exige exactamente una invocación con esos argumentos."),
  sqr("¿Qué significa usar 'It.IsAny<int>()' en lugar de un valor fijo como '1' dentro de un Setup, por ejemplo 'r => r.ObtenerPorId(It.IsAny<int>())'?","Que la configuración aplica sin importar qué valor int se pase como argumento a ObtenerPorId, en vez de solo coincidir con un valor exacto",["Que el argumento debe ser obligatoriamente distinto de 1","Que el método solo puede llamarse una única vez en todo el test","Que se ignorará cualquier llamada al método, sin importar el Setup"],0,"It.IsAny<T>() actúa como comodín en la configuración: hace que el Setup coincida con cualquier valor de ese tipo, útil cuando el argumento exacto no es relevante para ese test."),
  sqr("¿Qué es 'mockRepo.Object' en el fragmento, usado para construir ClienteServicio?","La instancia falsa generada por Moq que implementa realmente la interfaz IClienteRepositorio y que se le inyecta al servicio bajo prueba",["Una propiedad interna de Moq sin relación con la interfaz simulada","El resultado devuelto por la última llamada configurada en Setup","Un método usado exclusivamente para depuración del mock"],0,"'.Object' expone la implementación concreta y utilizable de la interfaz simulada, que es la que efectivamente se pasa a las dependencias del código bajo prueba."),
  sqr("¿Qué diferencia conceptual hay entre un 'stub' y un 'mock' como tipos de test double?","Un stub simplemente devuelve datos predefinidos sin que se verifique cómo fue llamado; un mock, además de poder devolver datos, permite verificar explícitamente que ciertas interacciones (llamadas) ocurrieron como se esperaba",["Son términos exactamente intercambiables sin ninguna diferencia real","Un stub solo puede usarse con clases selladas, y un mock solo con interfaces","Un mock nunca puede devolver ningún valor, solo un stub puede hacerlo"],0,"Aunque en la práctica muchas librerías (como Moq) permiten ambos usos con el mismo objeto, conceptualmente un stub se enfoca en proveer datos, mientras que un mock añade la capacidad de verificar comportamiento/interacciones."),
  sqr("¿Por qué usar un mock de IClienteRepositorio en lugar de una implementación real conectada a una base de datos al probar ClienteServicio?","Para aislar la prueba del comportamiento de ClienteServicio, evitando depender de una base de datos real, y así lograr un test más rápido, determinista y enfocado solo en la lógica del servicio",["Porque Moq no permite trabajar con clases concretas, solo con interfaces","Porque las bases de datos reales no pueden usarse nunca en ningún tipo de test","Porque el mock siempre produce resultados más precisos que una base de datos real"],0,"El objetivo del mock es aislar la unidad bajo prueba (ClienteServicio) de sus dependencias externas, permitiendo verificar su lógica propia sin la lentitud y variabilidad de una base de datos real."),
  sqr("Si se llama a servicio.Buscar(1) pero el código de ClienteServicio internamente invoca ObtenerPorId(2) en lugar de ObtenerPorId(1) por un bug, ¿qué pasaría con 'mockRepo.Verify(r => r.ObtenerPorId(1), Times.Once)'?","El Verify fallaría, ya que ObtenerPorId(1) nunca fue invocado realmente (se llamó con el argumento 2, que no coincide con la expectativa configurada)",["Pasaría igualmente, porque Verify solo revisa el nombre del método sin importar los argumentos","El mock lanzaría automáticamente una excepción antes de llegar al Verify","No se puede saber, Verify no tiene forma de detectar ese tipo de error"],0,"Verify compara la llamada específica (incluidos los argumentos indicados) contra las invocaciones realmente registradas en el mock; si el código bajo prueba llamó con un argumento distinto, la verificación falla y expone el bug."),
  sqr("¿Qué ocurre si se llama a un método del mock que NO tiene ningún Setup configurado para esa llamada específica, sobre un mock de una interfaz con un método que devuelve un tipo referencia?","Por defecto, Moq devuelve el valor por defecto de ese tipo (por ejemplo, null para un tipo referencia) en lugar de lanzar una excepción",["Siempre lanza una excepción indicando que falta el Setup","Ejecuta automáticamente la implementación real de producción","El test se marca como 'omitido' automáticamente sin ejecutarse"],0,"Sin un Setup específico, el comportamiento por defecto de Moq (en su modo estándar) es devolver el valor por defecto del tipo de retorno, no lanzar una excepción ni delegar a una implementación real."),
 ]},
 {id:"m15-parameterized-tests",title:"Tests parametrizados",summary:"Un test parametrizado ejecuta la misma lógica de prueba contra múltiples combinaciones de entrada/salida esperada, evitando duplicar código casi idéntico. En xUnit se usa [Theory] junto con [InlineData(...)] (valores fijos en el atributo) o [MemberData]/[ClassData] (fuentes de datos más complejas definidas en código).",code:"public class CalculadoraTests\n{\n    [Theory]\n    [InlineData(2, 3, 5)]\n    [InlineData(-1, 1, 0)]\n    [InlineData(0, 0, 0)]\n    public void Sumar_VariosCasos_DevuelveSumaCorrecta(int a, int b, int esperado)\n    {\n        var calculadora = new Calculadora();\n\n        int resultado = calculadora.Sumar(a, b);\n\n        Assert.Equal(esperado, resultado);\n    }\n}",questions:[
  sqr("¿Qué atributo de xUnit reemplaza a [Fact] cuando un método de prueba recibe parámetros y se ejecuta varias veces con distintos datos?","[Theory]",["[Fact]","[DataTest]","[Parametrized]"],0,"[Theory] marca un método de prueba que se ejecutará una vez por cada conjunto de datos provisto (por ejemplo, mediante InlineData), a diferencia de [Fact] que corre una única vez sin parámetros."),
  sqr("¿Cuántas veces se ejecutará el método 'Sumar_VariosCasos_DevuelveSumaCorrecta' del ejemplo, dado que tiene tres atributos [InlineData]?","Tres veces, una por cada conjunto de valores (a, b, esperado) declarado en cada [InlineData]",["Una sola vez, tomando solo el primer InlineData","Nueve veces, combinando todos los valores entre sí","Cero veces, porque [Theory] requiere [MemberData] obligatoriamente"],2,"Cada atributo [InlineData] agrega una ejecución independiente del método de prueba con esos argumentos específicos; con tres InlineData, xUnit reporta tres ejecuciones (casos) distintas."),
  sqr("En '[InlineData(-1, 1, 0)]' aplicado al método con parámetros (int a, int b, int esperado), ¿qué caso concreto está verificando esa ejecución del test?","Que Sumar(-1, 1) debe devolver 0, comprobando la suma de un negativo y un positivo que se cancelan",["Que Sumar(-1, 1) debe lanzar una excepción","Que el método Sumar no acepta números negativos","Que -1 y 1 deben ser iguales entre sí"],0,"Los valores de InlineData se asignan en orden a los parámetros del método: a=-1, b=1, esperado=0, verificando ese caso puntual de la suma."),
  sqr("Si se necesitaran fuentes de datos más complejas (por ejemplo, objetos generados dinámicamente en vez de literales simples), ¿qué alternativa a InlineData ofrece xUnit para [Theory]?","[MemberData] (o [ClassData]), que obtienen los casos de prueba desde una propiedad/método o una clase en vez de valores literales fijos en el atributo",["No existe alternativa, InlineData es la única opción posible en xUnit","Duplicar el método de prueba manualmente por cada caso adicional","Usar múltiples atributos [Fact] en el mismo método"],0,"Cuando los datos no pueden expresarse como literales de atributo (por ejemplo, objetos complejos), [MemberData] o [ClassData] permiten generarlos programáticamente en tiempo de ejecución."),
  sqr("¿Cuál es la ventaja principal de usar tests parametrizados en lugar de escribir un [Fact] casi idéntico por cada caso de prueba?","Se reduce la duplicación de código: la misma lógica de Arrange/Act/Assert se reutiliza para múltiples entradas, manteniendo el test más mantenible y fácil de extender con nuevos casos",["Los tests parametrizados se ejecutan siempre en paralelo automáticamente, a diferencia de los [Fact]","Los tests parametrizados no requieren ninguna aserción (Assert)","Permiten que el test pase incluso si algunos casos fallan, sin reportarlo"],0,"El valor de la parametrización es evitar copiar y pegar el mismo cuerpo de test para cada combinación de entrada/salida, agregando solo una nueva línea de datos por caso adicional."),
  sqr("Si uno de los tres casos de InlineData del ejemplo falla (por ejemplo, por un bug en Sumar), pero los otros dos pasan, ¿cómo se reporta típicamente en un test runner de xUnit?","Se reportan como ejecuciones (casos) independientes: el caso fallido se marca como fallo y los otros dos como éxito, dentro del mismo método de prueba parametrizado",["Todo el método se reporta como un único resultado, sin distinguir cuál caso falló","El test runner detiene la ejecución del proyecto completo ante el primer caso fallido","Los tres casos se combinan en un solo resultado que siempre es 'passed' si al menos uno pasa"],0,"xUnit trata cada conjunto de InlineData como una ejecución individual y reportable por separado, permitiendo identificar exactamente qué combinación de entradas causó el fallo."),
  sqr("¿Es necesario declarar el tipo de los parámetros del método de prueba (como 'int a, int b, int esperado') de forma coherente con los valores literales pasados en cada InlineData?","Sí, los valores de cada InlineData deben ser compatibles con los tipos declarados en la firma del método, o el test fallará al intentar invocarlo con esos datos",["No, InlineData puede pasar cualquier tipo sin relación con la firma del método","No, los parámetros del método de prueba siempre deben ser de tipo object","Solo es necesario para el primer InlineData, los demás son libres"],0,"Cada InlineData debe proveer valores compatibles con los parámetros declarados del método, ya que xUnit invoca el método pasando esos argumentos directamente."),
  sqr("¿Qué atributo de NUnit cumple un rol equivalente a [InlineData] de xUnit, proveyendo un conjunto de valores para una prueba parametrizada?","[TestCase(...)]",["[Theory]","[DataRow]","[MemberData]"],1,"NUnit usa [TestCase(valores...)] sobre un método marcado como [Test] para lograr el equivalente de la parametrización que xUnit hace con [Theory] + [InlineData]."),
  sqr("¿Qué atributo de MSTest cumple un rol equivalente a [InlineData] de xUnit para pruebas parametrizadas?","[DataRow(...)], combinado con [DataTestMethod] en lugar de [TestMethod]",["[Fact]","[TestCase]","[Theory]"],2,"MSTest usa [DataTestMethod] junto con uno o más [DataRow(valores...)] para lograr el equivalente de un test parametrizado, análogo a [Theory]+[InlineData] de xUnit."),
  sqr("¿Un método marcado con [Theory] pero sin ningún [InlineData], [MemberData] ni [ClassData] asociado se ejecuta normalmente como una prueba válida?","No; xUnit reporta ese caso como un error, porque una [Theory] necesita al menos una fuente de datos que le indique con qué argumentos ejecutarse",["Sí, se ejecuta una vez usando los valores por defecto de cada tipo de parámetro","Sí, se ejecuta exactamente igual que un [Fact] normal","Se omite silenciosamente sin ser reportada de ninguna forma"],0,"Una [Theory] depende de recibir datos externos para saber con qué argumentos invocarse; sin ninguna fuente de datos asociada, xUnit no puede generar ninguna ejecución válida y lo reporta como error."),
 ]},
 {id:"m15-coverage",title:"Cobertura y calidad",summary:"La cobertura de código mide qué porcentaje de líneas/ramas del código fue ejecutado durante la suite de pruebas; herramientas como coverlet se integran con 'dotnet test' para generar ese reporte. Cobertura alta NO garantiza calidad ni corrección: una línea puede ejecutarse sin que el test realmente verifique (con Assert) el comportamiento correcto en ese punto, dando una falsa sensación de seguridad.",code:"dotnet test --collect:\"XPlat Code Coverage\"\n// genera un reporte (por ejemplo con coverlet) del porcentaje de líneas/ramas ejecutadas por los tests",questions:[
  sqr("¿Qué mide exactamente la cobertura de código (code coverage)?","Qué porcentaje de las líneas o ramas del código fue efectivamente ejecutado al correr la suite de pruebas",["Qué porcentaje de los tests pasaron exitosamente","Cuántos bugs existen actualmente en el código","Qué tan rápido se ejecuta la suite de pruebas completa"],0,"La cobertura es una métrica de ejecución: indica qué partes del código fueron 'tocadas' por al menos un test, no si ese comportamiento fue verificado correctamente."),
  sqr("¿Puede un proyecto tener 100% de cobertura de líneas y aun así tener bugs importantes sin detectar?","Sí, porque una línea puede ejecutarse durante un test sin que ese test realmente contenga una aserción (Assert) que valide el comportamiento correcto en ese punto",["No, 100% de cobertura garantiza matemáticamente que no existen bugs","No, la cobertura de líneas siempre implica cobertura de todos los casos posibles","Sí, pero solo si el proyecto usa MSTest en lugar de xUnit"],0,"Cobertura mide ejecución, no verificación: un test puede recorrer una línea de código sin comprobar realmente que su resultado sea el esperado, dejando bugs sin detectar pese al 100%."),
  sqr("¿Qué herramienta mencionada en el ejemplo se integra comúnmente con 'dotnet test' para generar reportes de cobertura en proyectos .NET?","coverlet",["NuGet.exe","MSBuild.exe en modo aislado","dotnet publish"],0,"coverlet es una herramienta de cobertura de código multiplataforma ampliamente usada en el ecosistema .NET, integrable directamente con 'dotnet test'."),
  sqr("¿Qué diferencia hay entre cobertura de líneas (line coverage) y cobertura de ramas (branch coverage)?","La cobertura de líneas cuenta cuántas líneas se ejecutaron; la cobertura de ramas verifica si se ejecutaron todos los caminos posibles de decisión (por ejemplo, tanto el 'true' como el 'false' de un if)",["Son exactamente la misma métrica con nombres distintos","La cobertura de ramas solo aplica a bucles for, nunca a condicionales if","La cobertura de líneas es siempre más estricta que la de ramas"],1,"Un if puede tener su línea 'cubierta' por ejecutarse solo la rama verdadera, sin que la rama falsa jamás se haya probado; la cobertura de ramas distingue ese matiz, siendo más exigente que la de líneas."),
  sqr("¿Es recomendable fijar como objetivo obligatorio '100% de cobertura' para todo proyecto, sin ninguna consideración adicional?","No necesariamente: perseguir 100% a toda costa puede llevar a escribir tests triviales solo para 'tocar' líneas, sin agregar verificación real de valor, mientras se desatiende la calidad de las aserciones",["Sí, siempre es la meta ideal y no tiene ninguna desventaja práctica","No, porque .NET no permite superar el 80% de cobertura técnicamente","Sí, porque la cobertura del 100% es sinónimo directo de cero bugs"],0,"Un objetivo ciego de 100% puede incentivar tests de baja calidad que solo ejecutan código sin verificar comportamiento, priorizando el número sobre pruebas realmente significativas."),
  sqr("Si un método tiene una rama 'catch' que maneja una excepción específica, pero ningún test provoca esa excepción durante la ejecución, ¿esa rama aparece como cubierta en el reporte de cobertura?","No, esa rama del catch aparecería como no cubierta, ya que la herramienta de cobertura solo marca como ejecutado lo que realmente corrió durante los tests",["Sí, todas las ramas catch se consideran cubiertas automáticamente por convención","Sí, porque el compilador genera cobertura automática para el manejo de errores","Depende únicamente de si el método está marcado como público o privado"],0,"La cobertura refleja ejecución real; si ningún test provoca que ese catch específico se ejecute, el reporte mostrará esa rama como no cubierta, señalando un caso de error sin probar."),
  sqr("¿Qué tipo de métrica adicional a la cobertura ayuda a evaluar qué tan 'complejo' es un método (por ejemplo, cuántos caminos de decisión independientes tiene)?","La complejidad ciclomática, que cuenta el número de caminos de decisión distintos (if, bucles, switch, etc.) dentro de un método",["El número total de líneas en blanco del archivo","La cantidad de comentarios presentes en el método","El número de espacios usados para la indentación"],0,"La complejidad ciclomática es una métrica de calidad distinta de la cobertura, que cuantifica cuántos caminos de ejecución independientes existen en un método, útil para identificar código difícil de probar y mantener."),
  sqr("¿La cobertura de código reemplaza la necesidad de hacer revisión de código (code review) o pruebas de otro tipo, como pruebas de integración?","No, la cobertura es una métrica complementaria; no sustituye el juicio humano en la revisión de código ni otros tipos de prueba que validan comportamiento a un nivel distinto",["Sí, un alto porcentaje de cobertura hace innecesaria cualquier revisión de código","Sí, la cobertura de unit tests siempre reemplaza por completo las pruebas de integración","No tiene ninguna relación con la calidad general del software, es un número irrelevante"],0,"La cobertura es una señal útil pero parcial; no reemplaza la revisión de código, las pruebas de integración/end-to-end ni el diseño cuidadoso de casos de prueba significativos."),
  sqr("¿Qué riesgo específico existe al usar la cobertura de código como único criterio para evaluar el desempeño de un equipo o aprobar un pull request?","Puede incentivar a escribir tests superficiales que solo 'tocan' código para subir el número, en vez de tests que verifiquen comportamiento real y casos límite importantes",["Ningún riesgo, es una métrica perfectamente objetiva y suficiente por sí sola","El riesgo de que el proyecto deje de compilar automáticamente","El riesgo de que dotnet test deje de funcionar tras cierto porcentaje"],0,"Cuando la cobertura se convierte en un objetivo en sí mismo (más que un indicador), puede fomentar tests de bajo valor cuyo único propósito es ejecutar líneas, sin verificar realmente el comportamiento correcto."),
  sqr("¿Qué comando genera, según el ejemplo del paso, un reporte de cobertura al ejecutar las pruebas de un proyecto .NET?","dotnet test --collect:\"XPlat Code Coverage\"",["dotnet coverage run","dotnet test --coverage-report","dotnet build --analyze-coverage"],3,"El flag --collect:\"XPlat Code Coverage\" en 'dotnet test' activa la recolección de datos de cobertura multiplataforma, generando un archivo de reporte (por ejemplo, en formato Cobertura) tras la ejecución."),
 ]},
 {id:"m15-challenge",title:"Reto de testing",summary:"Reto integrador: escribir tests para una clase con una dependencia externa, combinando AAA, un mock de Moq para aislar esa dependencia, y un [Theory] con varios [InlineData] para cubrir distintos casos de entrada de un mismo método, incluyendo un caso de excepción.",code:"public interface INotificador\n{\n    void Enviar(string mensaje);\n}\n\npublic class ServicioPedidos\n{\n    private readonly INotificador _notificador;\n    public ServicioPedidos(INotificador notificador) => _notificador = notificador;\n\n    public decimal CalcularTotal(decimal precio, int cantidad)\n    {\n        if (cantidad <= 0) throw new ArgumentOutOfRangeException(nameof(cantidad));\n        decimal total = precio * cantidad;\n        _notificador.Enviar($\"Total calculado: {total}\");\n        return total;\n    }\n}\n\npublic class ServicioPedidosTests\n{\n    [Theory]\n    [InlineData(10, 2, 20)]\n    [InlineData(5.5, 3, 16.5)]\n    public void CalcularTotal_CantidadValida_DevuelveTotalYNotifica(decimal precio, int cantidad, decimal esperado)\n    {\n        var mockNotificador = new Mock<INotificador>();\n        var servicio = new ServicioPedidos(mockNotificador.Object);\n\n        decimal total = servicio.CalcularTotal(precio, cantidad);\n\n        Assert.Equal(esperado, total);\n        mockNotificador.Verify(n => n.Enviar(It.IsAny<string>()), Times.Once);\n    }\n}",questions:[
  sqr("¿Por qué ServicioPedidosTests usa un Mock<INotificador> en lugar de una implementación real de INotificador (por ejemplo, una que envíe un correo real)?","Para aislar el test de efectos secundarios externos (como enviar un correo real) y poder verificar que Enviar fue invocado, sin depender de infraestructura real ni de que esta tenga éxito",["Porque INotificador no puede implementarse de ninguna otra forma en C#","Porque ServicioPedidos solo compila si recibe un Mock, nunca una implementación real","Porque Moq reemplaza automáticamente todas las interfaces del proyecto, sin que el test lo controle"],0,"El propósito del mock es sustituir la dependencia real (que tendría efectos externos indeseados en un test) por un doble controlable, permitiendo probar la lógica de ServicioPedidos de forma aislada."),
  sqr("Si se llamara 'servicio.CalcularTotal(10, 0)' (cantidad igual a 0), ¿qué debería ocurrir según el código de CalcularTotal?","Se lanza ArgumentOutOfRangeException antes de calcular el total o de notificar, ya que la validación 'if (cantidad <= 0)' se ejecuta primero",["Devuelve 0 como total sin lanzar ninguna excepción","Notifica igualmente con un mensaje de total 0","Lanza DivideByZeroException por la operación con cantidad 0"],0,"La guarda al inicio del método valida explícitamente cantidad <= 0 y lanza la excepción antes de llegar a cualquier cálculo o notificación."),
  sqr("Para agregar un caso de prueba que verifique específicamente que CalcularTotal(10, 0) lanza ArgumentOutOfRangeException, ¿qué construcción de xUnit sería la más apropiada dentro de un nuevo [Fact]?","Assert.Throws<ArgumentOutOfRangeException>(() => servicio.CalcularTotal(10, 0));",["Assert.Equal<ArgumentOutOfRangeException>(servicio.CalcularTotal(10, 0));","[InlineData(10, 0, \"excepcion\")] sobre el mismo método CalcularTotal_CantidadValida_DevuelveTotalYNotifica","Assert.True(servicio.CalcularTotal(10, 0) == null);"],1,"Assert.Throws<T> envuelve la invocación en un delegado y verifica que se lance exactamente el tipo de excepción esperado, que es la forma idiomática de probar casos de error en xUnit."),
  sqr("En el test parametrizado mostrado, ¿qué verifica exactamente 'mockNotificador.Verify(n => n.Enviar(It.IsAny<string>()), Times.Once)'?","Que el método Enviar del notificador (mockeado) haya sido llamado exactamente una vez, sin importar qué texto exacto se le haya pasado como mensaje",["Que Enviar nunca haya sido llamado durante la prueba","Que el mensaje enviado sea exactamente igual a 'Total calculado: 20'","Que ServicioPedidos implemente la interfaz INotificador directamente"],0,"It.IsAny<string>() permite que el Verify coincida sin importar el contenido exacto del mensaje, mientras Times.Once exige que la llamada haya ocurrido una única vez durante el test."),
  sqr("¿Por qué el segundo caso '[InlineData(5.5, 3, 16.5)]' es válido para el parámetro 'precio' declarado como decimal en la firma del método de prueba?","Porque 5.5 y 16.5 pueden interpretarse como literales compatibles con decimal en ese contexto de InlineData, cumpliendo con el tipo declarado en la firma",["Porque InlineData ignora completamente los tipos declarados en la firma del método","Porque 'decimal' en C# es sinónimo exacto de 'double' sin ninguna diferencia","Porque xUnit convierte automáticamente cualquier valor a string antes de pasarlo"],0,"Los valores literales de InlineData deben ser compatibles con el tipo de parámetro correspondiente; para decimal, un valor como 5.5 se puede proveer válidamente en ese contexto de datos de prueba."),
  sqr("¿Qué patrón AAA se puede identificar dentro del cuerpo del método CalcularTotal_CantidadValida_DevuelveTotalYNotifica?","Arrange: crear el mock y el servicio; Act: llamar a servicio.CalcularTotal(precio, cantidad); Assert: verificar el total devuelto y que Enviar se llamó una vez",["Todo el método es únicamente Act, sin ninguna sección de Arrange ni Assert","Arrange y Assert están fusionados en una sola línea obligatoriamente","El patrón AAA no puede aplicarse a tests que usan Theory con InlineData"],1,"El método sigue AAA con claridad: primero prepara el mock/servicio (Arrange), luego ejecuta la acción bajo prueba (Act), y finalmente verifica tanto el resultado como la interacción esperada con el mock (Assert)."),
  sqr("Si se quisiera medir qué porcentaje de las ramas de CalcularTotal (incluyendo la del throw por cantidad inválida) está cubierto por la suite de tests actual, ¿qué haría falta que el reporte de cobertura muestre 100% de cobertura de ramas en ese método?","Agregar al menos un test que efectivamente dispare la rama del throw (cantidad <= 0), además de los casos ya cubiertos con cantidades válidas",["Nada adicional, los dos InlineData actuales ya cubren automáticamente esa rama","Aumentar el número de InlineData con cantidades válidas adicionales, sin relación con la rama del throw","Renombrar el método de prueba para que incluya la palabra 'Coverage'"],0,"La cobertura de ramas exige que cada camino de decisión se haya ejecutado al menos una vez; como ningún test actual pasa cantidad <= 0, esa rama del throw queda sin cubrir hasta que se agregue un caso específico para ella."),
  sqr("¿Qué ocurriría con 'mockNotificador.Verify(n => n.Enviar(It.IsAny<string>()), Times.Once)' si, por un bug, CalcularTotal dejara de llamar a _notificador.Enviar(...) por completo?","El Verify fallaría, reportando que se esperaba exactamente una llamada a Enviar pero se registraron cero, señalando el bug de la notificación faltante",["El Verify pasaría igual, porque Times.Once no falla nunca en la práctica","El test completo se saltaría automáticamente sin ejecutarse","El mock lanzaría una excepción antes de llegar a Assert.Equal"],0,"Verify compara explícitamente el número real de invocaciones observadas contra lo esperado (Times.Once); si Enviar nunca se llamó, la expectativa de una llamada no se cumple y el test falla, exponiendo el bug."),
  sqr("¿Por qué es valioso, en este reto, combinar tanto un mock (para INotificador) como un test parametrizado (para distintos precios/cantidades) en la misma suite de pruebas de ServicioPedidos?","Porque cada técnica cubre un aspecto distinto: el mock aísla la dependencia externa y verifica la interacción con ella, mientras la parametrización cubre múltiples combinaciones de entrada de la lógica de cálculo sin duplicar código de test",["Porque xUnit exige obligatoriamente usar Moq dentro de cualquier método marcado con [Theory]","Porque de otra forma CalcularTotal no podría compilar","Porque combinar ambas técnicas siempre duplica automáticamente la cobertura de código sin agregar ningún test adicional"],0,"Ambas técnicas resuelven problemas distintos y complementarios: aislar dependencias externas (mocks) y evitar duplicación de tests casi idénticos para múltiples entradas (parametrización); juntas dan una suite más completa y mantenible."),
  sqr("Si ServicioPedidos no recibiera INotificador por constructor (inyección de dependencias) sino que creara internamente 'new NotificadorEmailReal()' dentro de CalcularTotal, ¿seguiría siendo posible sustituirlo fácilmente por un mock en el test?","No fácilmente: al crear la dependencia concreta internamente (sin inyección), el test no tendría forma de reemplazarla por el mock, dificultando aislar la prueba de ese efecto externo real",["Sí, exactamente igual que en el ejemplo actual, sin ningún cambio necesario","Sí, porque Moq puede interceptar automáticamente cualquier 'new' dentro de cualquier clase sin configuración","No importaría en absoluto para la testabilidad del método"],0,"La inyección de dependencias (recibir INotificador por constructor) es precisamente lo que permite sustituir la implementación real por un mock en los tests; sin ella, la clase queda fuertemente acoplada a una implementación concreta difícil de aislar."),
 ]},
];
